/* ⛔ GENERATED by kit/build.mjs from i18n/uk.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["uk"] = {"hero.headline":"<span class=\"hl-muted\">Покладіть на скло. Натисніть START.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Перетягніть копію.</span>","hero.cycle":"Перетягніть копію.|Перетягніть MIDI.|Перетягніть аудіо.","hero.sub":"Аудіо на вході, MIDI на виході. MIDI на вході, аудіо на виході. Безкоштовно, офлайн і на 100% без ШІ.","hero.chipStandalone":"Окремий застосунок","what.title":"Що це таке","what.p1":"Перетворення лупу на MIDI або MIDI-файлу на аудіо зазвичай означає ланцюжок інструментів, експорт, повторний імпорт і чимало здогадок про те, що вийшло.","what.p2":"Flipcopy — це копіювальний апарат. Покладіть аудіофайл або MIDI-файл на його скло, і він надрукує оригінал — справжню форму хвилі або кожну ноту з її даними. Натисніть зелену кнопку START, і він надрукує копію в іншій формі: аудіо на вході — MIDI на виході; MIDI на вході — аудіо на виході.","what.p3":"Копія виходить як надрукована сторінка з яскраво-зеленою рамкою навколо кліпу. Візьміть рамку і перетягніть її на доріжку у вашій DAW. Кожна копія — це справжній файл, який лишається на місці, тож ваш проєкт ніколи його не втратить.","see.title":"Подивіться, як він копіює","see.intro":"Копір, відрендерений у Blender: оригінал лягає на скло, кришка закривається, лампа проходить, і копія виїжджає на лоток.","see.start":"Натисніть START, щоб побачити, як він копіює","see.audioToMidi":"Аудіо на вході, MIDI на виході: по сторінці на кожен шар — мелодія, акорди, басова лінія та контрмелодія.","see.midiToAudio":"MIDI на вході, аудіо на виході.","features.title":"Що всередині","features.copier.title":"Копір","features.copier.body":"Фотореалістичний копіювальний апарат, відрендерений у Blender. Покладіть кліп на скло, і він надрукує справжню річ: кожну ноту або справжню форму хвилі з її темпом, довжиною і рівнями.","features.start.title":"Зелена кнопка START","features.start.body":"Перетягування кліпу лише кладе його на скло. Нічого не копіюється, доки ви не натиснете START, тож не станеться нічого, про що ви не просили.","features.audioToMidi.title":"Аудіо → MIDI","features.audioToMidi.body":"Барабани, бас, мелодія, контрмелодія й акорди з лупу — кожен на своїй сторінці, надруковані поспіль за одне сканування, щоб перетягнути їх у DAW окремими доріжками.","features.midiToAudio.title":"MIDI → аудіо","features.midiToAudio.body":"MIDI-файл, зіграний на справжньому інструменті, а барабани — через драм-машину, надрукований як аудіофайл, який можна перетягнути.","features.drag.title":"Перетягніть копію","features.drag.body":"Кожна сторінка носить яскраво-зелену рамку навколо свого кліпу. Візьміть її і киньте на доріжку. Файл справжній, і Flipcopy ніколи його не перезаписує і не видаляє.","features.browser.title":"Браузер","features.browser.body":"Файловий браузер із програвачем для попереднього прослуховування, з Freally Oscillate. Він показує форму хвилі для аудіо і ноти для MIDI, а MIDI відтворює через той самий інструмент, що використовує копія.","features.daw.title":"У будь-якій DAW","features.daw.body":"CLAP, VST3 і AU, а також окремий застосунок для роботи без DAW і для Pro Tools. Windows, macOS і Linux.","features.free.title":"Безкоштовно, офлайн, без ШІ","features.free.body":"Без тарифів, без облікового запису, без телеметрії, без мережі, без моделі. Класична обробка сигналу, забезпечена перевіркою збірки, а не просто обіцяна.","docs.language.title":"Мови","docs.language.p1":"Flipcopy розмовляє вісімнадцятьма мовами. Він запускається мовою вашої системи; щоб обрати іншу, відкрийте «Налаштування» через шестерню вгорі браузера і виберіть потрібну. Вибір застосовується до всіх копій Flipcopy на комп'ютері.","ladder.title":"Шлях до 1.0","ladder.intro":"По одному рядку на версію. Це та сама драбина, якою йде закритий план, — якщо рухається одна, рухається й інша, а перевірка збірки їх звіряє.","ladder.rung.v0.1.0":"Фундамент: плагін завантажується як CLAP, VST3 і AU та як окремий застосунок, пропускає ваш звук недоторканим, просить прийняти ліцензію, і працюють усі перевірки якості.","ladder.rung.v0.2.0":"Копір і перша копія: апарат у вікні, зелена кнопка START і MIDI-файл, скопійований в аудіо, яке ви перетягуєте просто у свою DAW.","ladder.rung.v0.3.0":"Аудіо в MIDI: покладіть луп на скло, натисніть START і перетягніть його барабани, бас, мелодію та акорди у вигляді MIDI.","ladder.rung.v0.4.0":"Файловий браузер і програвач попереднього прослуховування: знайдіть семпл або MIDI-кліп, послухайте, подивіться й перетягніть його на скло. Усе найнеобхідніше вже тут.","ladder.rung.v0.5.0":"Сенсорний екран: налаштування копіювання, інструменти для ваших копій, формати файлів та історія всіх зроблених вами копій.","ladder.rung.v0.5.5":"Студія: відкрийте будь-яку копію в піано-ролі, змініть її ноти, послухайте з будь-яким інструментом і надрукуйте правку як нову копію.","ladder.rung.v0.5.7":"Мікшер і ваші власні інструменти: реалістичні ручки для кожної партії, ваші ударні кіти й семпли, обране та одна бібліотека інструментів на всі застосунки Freally.","ladder.rung.v0.5.9":"Світла тема: сучасна, витончена світла тема в зеленому кольорі Freally поряд із темною, з тим самим реалістичним обладнанням в обох.","ladder.rung.v0.6.0":"У кожній DAW: збереження разом із проєктом, скан просто з доріжки, перетягування будь-якого файлу з браузера на доріжку й вісім копірів одночасно.","ladder.rung.v0.7.0":"Окремий застосунок на повну силу: одне вікно за раз, відкривається там, де ви його залишили, грає на вибраному виході, а відкритий ним файл одразу лягає на скло. Перевірено у WebKit — рушії macOS і Linux, а налаштування тепер розділами.","ladder.rung.v0.8.0":"Точніші копії, ударні на підписаних доріжках і лупа над кожною сторінкою, апарат із поштовхом і тінню, кожна копія на повній швидкості й кожен модуль читання файлів, перевірений на пошкоджених файлах.","ladder.rung.v1.0.0-beta":"Зміцнення: шлях туди й назад — відрендерте MIDI-файл в аудіо, перетягніть сторінку назад на скло, натисніть START, і це знову MIDI — і «Вокальна лінія» для проспіваної партії. Перевірка оновлень, яка вимкнена, доки ви не скажете «так», і лише повідомляє, що вийшла нова версія. Інсталятор для Windows і install.sh для Linux. Кожен крайній випадок покрито тестом, кожен крок доступний із клавіатури, усі 18 мов вичитано. Завантажити, як і раніше, нічого до 1.0.0.","ladder.rung.v1.0.0-rc":"Реліз-кандидат: кожен файл переглянуто, кожен хост перевірено вручну.","ladder.rung.v1.0.0":"Реліз — і перші завантаження, які цей сайт будь-коли пропонував.","ladder.rung.v1.1.0":"Автоподавач документів: копіюйте цілу папку за один раз.","ladder.rung.v1.3.0":"Нотні копії: MusicXML і друк у нотному записі.","ladder.rung.v1.4.0":"Мости до інших продуктів Freally.","ladder.rung.v1.5.0":"Pro Tools як плагін (AAX), якщо умови Avid дозволять це для безкоштовного продукту.","ladder.rung.v1.6.0":"Копії грува та чорнові копії стемів без ШІ.","ladder.note":"Готова версія зібрана і позначена тегом. Це не завантаження: їх немає і не буде до 1.0.0.","honest.title":"Те, що більшість сайтів розміщують унизу сторінки","honest.transcription.title":"MIDI-копія міксу — це транскрипція","honest.transcription.body":"Знаходити ноти в готовому міксі важко, і Flipcopy робить це класичною обробкою сигналу, а не моделлю. Він пропустить деякі ноти і почує ті, яких немає. Він друкує те, що знайшов, і каже, чого не зміг зробити.","honest.chords.title":"Акорди повертаються як послідовність","honest.chords.body":"Акордова партія друкується як послідовність, якій вона слідує, а не точне розташування нот, яке було зіграно, і сторінка прямо про це каже.","honest.measured.title":"Виміряно, а не обіцяно","honest.measured.body":"Кожен показник точності — це нижня межа, яку має тримати кожна збірка; його виміряно на тестовому наборі з 30 лупів, стемів і MIDI-файлів: фортепіанна лінія, прочитана назад, — 96% нот; основні тони акордів — 75% тактів; лінія провідного вокалу — 99% у тональності. MP3 і досі читається трохи інакше, ніж його WAV, а м’які акорди педу (pad) поки не читаються.","honest.downloads.title":"До версії 1.0.0 завантажень немає","honest.downloads.body":"На цій сторінці немає ні бети, ні попереднього білда, ні раннього доступу. Копір, що працює наполовину, гірший за той, якого поки немає.","honest.network.title":"Він ніколи не виходить у мережу","honest.network.body":"Плагін і окремий застосунок узагалі не містять мережевого коду, і перевірка збірки не пройде, якщо такий код буде додано. Єдиний виняток — перевірка оновлень, вимкнена, доки ви не скажете «так»: окрема програма читає один публічний файл, а Flipcopy лише повідомляє, що вийшла нова версія.","site.tagline":"Покладіть на скло. Натисніть START. Перетягніть копію.","footer.licence":"Пропрієтарне ПЗ — усі права захищено. © Mike Weaver. Наразі безкоштовне для використання; майбутні версії можуть продаватися. Не з відкритим кодом.","footer.yours":"Зроблені вами копії належать вам — тією мірою, якою скопійовані файли були вашими для використання. Автор Flipcopy не претендує на права щодо них.","featuresPage.lead":"Копіювальний апарат для ваших кліпів. Аудіо на вході, MIDI на виході, розкладене на партії; MIDI на вході, аудіо на виході, через справжні інструменти — і кожна копія перетягується просто у вашу DAW.","featuresPage.version":"Ця сторінка описує Freally Flipcopy версії 1.0: усе, що на ній є, входить до 1.0, а нічого із запланованого після 1.0 тут немає.","featuresPage.numbers.directions":"напрямки: аудіо → MIDI і MIDI → аудіо","featuresPage.numbers.parts":"видів партій, які він копіює: ударні, бас, мелодія, контрмелодія, акорди та вокальна лінія","featuresPage.numbers.instruments":"інструментів, на яких можна зіграти MIDI-копію","featuresPage.numbers.bars":"тактів: найдовший луп, який приймає скло","featuresPage.numbers.formats":"форматів файлів, які він записує: MIDI, WAV, AIFF, FLAC і MP3","featuresPage.numbers.plugins":"формати плагінів, а також окремий застосунок","featuresPage.numbers.systems":"операційні системи: Windows, macOS і Linux","featuresPage.numbers.languages":"мов","featuresPage.numbers.ai":"моделей ШІ","featuresPage.numbers.price":"ціна зараз","featuresPage.free.title":"Зараз безкоштовно","featuresPage.free.body":"Усе, що Flipcopy вміє зараз, безкоштовне для всіх: без платного тарифу, без підписки, без облікового запису і без пробного періоду, що закінчується. Зроблені вами копії належать вам — тією мірою, якою скопійовані файли були вашими для використання.","featuresPage.cards.title":"Що вміє версія 1.0","featuresPage.cards.copier.title":"Копір","featuresPage.cards.copier.body":"Фотореалістичний копіювальний апарат, відрендерений у Blender, із власними звуками. Покладіть кліп на скло, і він надрукує справжню річ — форму хвилі або кожну ноту — з її даними: темпом, довжиною, нотами чи рівнями.","featuresPage.cards.start.title":"Копіює лише зелена кнопка START","featuresPage.cards.start.body":"Перетягування кліпу лише кладе його на скло. Нічого не копіюється, доки ви не натиснете START; STOP скасовує сканування, а HOME очищає скло, тож не стається нічого, про що ви не просили.","featuresPage.cards.audioToMidi.title":"Аудіо → MIDI, по партіях","featuresPage.cards.audioToMidi.body":"Луп виходить у вигляді партій, з яких він складається, — ударні на власних лініях, бас, мелодія, контрмелодія, якщо вона є, і акордова послідовність — по одній сторінці й одному MIDI-файлу на кожну, за одне сканування. Партія, якої немає, сторінки не отримує. Або скопіюйте окремо вокальну лінію.","featuresPage.cards.midiToAudio.title":"MIDI → аудіо, через справжні інструменти","featuresPage.cards.midiToAudio.body":"MIDI-файл, зіграний на будь-якому з 1,648 інструментів, які використовує Freally MIDI Master, — свій звук для кожної партії та драм-машина для ударних — і надрукований як одна аудіосторінка на партію, плюс увесь мікс. WAV, AIFF, FLAC або MP3, з частотою дискретизації та розрядністю, які ви оберете.","featuresPage.cards.drag.title":"Перетягніть копію","featuresPage.cards.drag.body":"Кожна сторінка носить яскраво-зелену рамку: візьміть її і киньте файл на доріжку. Або перетягніть усю стопку — «Усі партії» лягає окремою доріжкою на кожну партію, «Повний мікс» — одним кліпом. Кожен файл названо так, як його має показати ваша DAW, наприклад Loop - Bassline - 120 BPM - C# Minor.","featuresPage.cards.copies.title":"Копії — назавжди","featuresPage.cards.copies.body":"Кожна копія — це справжній перевірений файл у вашій теці «Копії»: з номером, і його ніколи не переміщують, не перезаписують і не видаляють, тож проєкт, який його використовує, ніколи його не втратить. Гортайте всі зроблені вами копії, збережіть будь-яку ще раз, покажіть її в теці або знову покладіть на скло.","featuresPage.cards.browser.title":"Браузер і програвач попереднього прослуховування","featuresPage.cards.browser.body":"Файловий браузер із Freally Oscillate: до 128 тек, назад і вперед, теги, зірочки та навігація з клавіатури. Попереднє прослуховування показує справжню форму хвилі або ноти, відтворює MIDI тим самим звуком, що й копія, і програє готову стопку синхронно, з A/B-порівнянням з оригіналом.","featuresPage.cards.studio.title":"Студія","featuresPage.cards.studio.body":"Відкрийте будь-яку копію в піано-ролі, по вкладці на партію, і редагуйте її точно як у Freally MIDI Master. Послухайте її з будь-яким інструментом, сформуйте звук на мікшері з реалістичними ручками, зіграйте на власному ударному кіті чи одному зі своїх семплів і відправте правку назад на скло, щоб надрукувати як нову копію.","featuresPage.cards.settings.title":"Налаштування на сенсорному екрані","featuresPage.cards.settings.body":"Власний екран копіра містить налаштування копіювання: які партії, сітка і свінг, темп і звідки він береться, звук для кожної партії, формат файлу і хвіст. Перевірка збірки контролює, що кожне налаштування справді змінює копію.","featuresPage.cards.daw.title":"У кожній DAW","featuresPage.cards.daw.body":"CLAP і VST3 на Windows, macOS і Linux, AU на macOS та окремий застосунок для роботи без DAW — а для Pro Tools через перетягування. Зберігається разом із проєктом, безпечно працює в багатьох екземплярах одночасно і вміє сканувати просто з доріжки.","featuresPage.cards.lightDark.title":"Світла й темна теми","featuresPage.cards.lightDark.body":"Темна й світла теми, обидві в зеленому кольорі Freally, з єдиного сучасного дизайну, спільного для всіх застосунків Freally, з регуляторами, фейдерами, повзунками, перемикачами й клавішами, відрендереними в Blender для кожної з них. Копір заново відрендерено на власному тлі кожної теми, тож він завжди стоїть в одній кімнаті.","featuresPage.cards.offline.title":"Офлайн, приватно, без ШІ","featuresPage.cards.offline.body":"Без телеметрії та без моделі. Кожну копію створює класична обробка сигналу, а плагін і застосунок ніколи не виходять у мережу. Єдиний виняток — перевірка оновлень, вимкнена, поки ви самі її не увімкнете, яку запускає окрема програма.","featuresPage.compare.title":"Пліч-о-пліч із комерційними інструментами","featuresPage.compare.intro":"Freally Flipcopy 1.0 поруч із комерційними інструментами, якими продюсери перетворюють аудіо на MIDI і MIDI на аудіо. Кожну клітинку іншого продукту взято з власних сторінок його виробника, перевірених у жовтні 2026 року, а ціни — це роздрібні ціни у США станом на жовтень 2026 року.","featuresPage.compare.feature":"Можливість","featuresPage.compare.row.price":"Ціна (USD, жовтень 2026)","featuresPage.compare.freeToday":"Зараз безкоштовно","featuresPage.compare.row.audioToMidi":"Перетворює аудіо на MIDI","featuresPage.compare.legend.yes":"є","featuresPage.compare.row.parts":"Розкладає луп на партії, кожну в окремий MIDI-файл","featuresPage.compare.legend.no":"немає","featuresPage.compare.note.byPitch":"розділяє ноти, а не інструменти","featuresPage.compare.note.byInstrument":"за інструментами","featuresPage.compare.legend.partly":"частково","featuresPage.compare.note.byHand":"спершу стеми, потім кожен вручну","featuresPage.compare.row.midiToAudio":"Перетворює MIDI на аудіо вбудованими інструментами","featuresPage.compare.legend.unknown":"не перевірено","featuresPage.compare.note.playbackOnly":"відтворює, але не експортує аудіо","featuresPage.compare.row.drag":"Перетягування результату просто на доріжку DAW","featuresPage.compare.note.anyFile":"кожна сторінка й будь-який файл у його браузері","featuresPage.compare.note.ara":"у деяких DAW, через ARA","featuresPage.compare.row.plugin":"Працює в DAW як плагін","featuresPage.compare.note.link":"надсилає аудіо у власний застосунок","featuresPage.compare.note.ownDaw":"лише у власній DAW","featuresPage.compare.note.appOnly":"лише окремий застосунок","featuresPage.compare.row.scan":"Бере звук просто з доріжки у вашій DAW","featuresPage.compare.note.audioOrNotes":"її звук або ноти, які вона отримує","featuresPage.compare.note.transfer":"аудіо, через Transfer або ARA","featuresPage.compare.row.systems":"Windows, macOS і Linux","featuresPage.compare.row.lightDark":"Світла й темна теми оформлення","featuresPage.compare.row.noAi":"Без ШІ та машинного навчання","featuresPage.compare.note.aiStems":"використовує для розділення на стеми","featuresPage.compare.summaryTitle":"Коротко","featuresPage.compare.summary":"Коротко: усе це має лише Flipcopy — обидва напрямки, партії, перетягування, плагін, усі три системи та без ШІ.","featuresPage.compare.theyWinTitle":"У чому вони сильніші","featuresPage.compare.theyWin":"Де виграють вони: Melodyne Studio, RipX, AnthemScore і Ableton Live можуть розписати окремі ноти акорду з поліфонічного запису (Melodyne — лише з інструмента, записаного окремо); Flipcopy натомість дає акордову послідовність і прямо про це каже. RipX, Ableton Live Suite і Logic Pro також розділяють мікс на аудіостеми, чого Flipcopy 1.0 не робить.","featuresPage.compare.asOf":"Стовпець Flipcopy — це версія 1.0, яка ще не вийшла, а його ціна — сьогоднішня: Flipcopy зараз безкоштовний, а майбутні версії можуть продаватися. Інші продукти теж змінюються; таблиця актуальна на жовтень 2026 року.","featuresPage.why.title":"Чому він зроблений саме так","featuresPage.why.dsp.title":"Класична обробка сигналу","featuresPage.why.dsp.body":"Атаки нот, відстеження висоти, хрома і детермінований рендерер — і жодної моделі. Той самий файл, ті самі налаштування і та сама версія щоразу дають ту саму копію, байт у байт.","featuresPage.why.print.title":"Що бачите, те й перетягуєте","featuresPage.why.print.body":"Кожна сторінка малюється з байтів файлу, який вона перетягує. Ноти, темп і довжина на папері — це ті самі ноти, темп і довжина, що потрапляють на вашу доріжку.","featuresPage.why.honest.title":"Чесні копії","featuresPage.why.honest.body":"Жодних порожніх сторінок і жодних здогадок, виданих за транскрипцію. Акорди кажуть, що вони — послідовність, задовгий для скла кліп відхиляється із зазначенням довжини, а не обрізається, а вокальна лінія, залишена як є, прямо про це каже.","featuresPage.why.local.title":"Усе лишається на вашому комп'ютері","featuresPage.why.local.body":"Без телеметрії та без хмари. Ваші файли та копії ніколи не покидають ваш комп'ютер, а перевірка збірки не пройде, якщо до плагіна чи застосунку колись додадуть мережевий код.","featuresPage.why.tempo.title":"Він слідує за вашою DAW","featuresPage.why.tempo.body":"Плагін зчитує темп вашого проєкту і ніколи його не змінює, а кожен темп, який друкує Flipcopy, називає своє джерело: луп, файл, його назву, вашу DAW або вас.","featuresPage.why.mix.title":"Ніщо не потрапить у ваш мікс випадково","featuresPage.why.mix.body":"Звуки копіра і попереднє прослуховування тихо звучать через плагін і ніколи не потрапляють у bounce. Поки вони мовчать, звук вашої доріжки проходить недоторканим.","featuresPage.coming.title":"Що ще попереду","featuresPage.coming.intro":"Кажемо прямо, бо список можливостей, який приховує свої прогалини, не варто читати. Ця сторінка описує версію 1.0, а Flipcopy будується щабель за щаблем: не все на ній уже зроблено. Кожен щабель на шляху до 1.0 позначено його станом.","featuresPage.limits.title":"Чого 1.0 не робить","featuresPage.limits.chords":"Він не розписує кожну ноту акорду, почутого в зведеному записі: акорди повертаються як послідовність, і сторінка прямо про це каже.","featuresPage.limits.loops":"Він копіює лупи, а не цілі пісні: скло приймає кліпи до 16 тактів, а довший відхиляє із зазначенням довжини.","featuresPage.limits.stems":"Він не розділяє зведений запис на аудіостеми: партії лупу виходять як MIDI.","featuresPage.limits.aax":"Це не плагін для Pro Tools: у Pro Tools скористайтеся окремим застосунком і перетягніть копію на таймлайн.","featuresPage.coming.downloads":"До версії 1.0 завантажень немає, і на цій сторінці їх теж немає.","docs.intro":"Це посібник Flipcopy: кожна частина вікна, кожне налаштування й кожна клавіша, з анотованим знімком екрана поруч із кожною процедурою. Він зростає з кожною версією.","docs.start.title":"Початок роботи","docs.agreement.title":"Ліцензійна угода","docs.window.title":"Вікно","docs.copier.title":"Як зробити копію","docs.pages.title":"Як читати сторінку","docs.screen.title":"Сенсорний екран","docs.copySettings.title":"Налаштування копіювання","docs.instruments.title":"Інструменти","docs.copies.title":"Ваші копії","docs.studio.title":"Студія","docs.mixer.title":"Мікшер і ваші власні звуки","docs.browser.title":"Браузер","docs.preview.title":"Програвач попереднього прослуховування","docs.daw.title":"У вашій DAW","docs.standalone.title":"Самостійний застосунок і Pro Tools","docs.settings.title":"Налаштування","docs.appearance.title":"Світла й темна теми","docs.trouble.title":"Усунення несправностей","docs.report.title":"Якщо щось пішло не так","docs.keys.title":"Клавіатурні скорочення","docs.privacy.title":"Приватність і мережа","docs.build.title":"Збирання з вихідного коду","docs.start.p1":"Flipcopy працює всередині вашої DAW як плагін CLAP, VST3 або AU, або окремо як самостійний застосунок. Розмістіть його на будь-якій аудіодоріжці: він пропускає звук доріжки точнісінько таким, яким він надходить, тож його безпечно лишити на місці.","docs.start.standalone":"Самостійний застосунок працює лише в одному екземплярі: відкрийте його знову — і його вікно вийде на передній план. Він відкривається там, де ви його залишили. У «Налаштуваннях» пункт «Аудіовихід» вибирає пристрій, через який він звучить, з наступного запуску. Відкрийте файл за допомогою Flipcopy («Відкрити за допомогою» у Провіднику або подвійне клацання, щойно Flipcopy стане програмою для файлів такого типу) — і він ляже на скло, готовий до START; якщо Flipcopy вже відкрито, файл бере це вікно.","docs.demo.audioOutput":"Аудіовихід","docs.start.linux":"У Linux вікно плагіна малює WebKitGTK — найслабше місце будь-якого плагіна для Linux. Якщо вікно Flipcopy у вашій DAW працює неправильно, використовуйте поруч самостійний застосунок: він робить усе те саме, що й плагін, окрім «Скан із доріжки», а його сторінки так само перетягуються на ваші доріжки.","docs.start.p2":"До версії 1.0.0 завантажень немає, а вихідний код закритий.","docs.agreement.p1":"Під час першого запуску Flipcopy показує свою ліцензійну угоду. Дочитайте її до кінця, і кнопка «Погоджуюся» стане доступною. Поки ви не погодитеся, Flipcopy нічого не читає, не копіює і нічого не додає до звуку вашої доріжки.","docs.agreement.p2":"Ваша відповідь зберігається на вашому комп'ютері й використовується всіма відкритими копіями Flipcopy — у кожній DAW і в окремому застосунку. Якщо ви відмовитеся, оберіть «Прочитати знову», коли будете готові.","docs.window.p1":"З одного боку — браузер, а під ним закріплений програвач попереднього прослуховування. Решта вікна — це сцена, де стоїть копір. Перетягніть роздільну лінію між ними, щоб зробити браузер ширшим або вужчим, або виділіть її й скористайтеся клавішами зі стрілками.","docs.window.p2":"Натисніть Ctrl+B (Cmd+B на Mac) або кнопку на краю браузера, щоб згорнути браузер разом із попереднім прослуховуванням: сцена займе все вікно. Натисніть ще раз, і вони повернуться з тією шириною, з якою ви їх залишили. Flipcopy запам’ятовує ваш вибір.","docs.shot.window.alt":"Вікно Flipcopy: браузер ліворуч у червоній рамці з номером 1, закріплений під ним програвач попереднього прослуховування з номером 2, кнопка на краю браузера, яка згортає їх, з номером 3 і сцена, де стоїть копір, з номером 4.","docs.shot.window.caption":"Вікно: браузер (1) із програвачем попереднього прослуховування під ним (2), кнопка, яка згортає їх (3), і сцена, де стоїть копір (4).","docs.copier.p1":"Покладіть аудіо- або MIDI-файл на скло: киньте його із Провідника чи Finder будь-куди у вікні, перетягніть його з браузера або зі смуги попереднього прослуховування на копір, натисніть Enter на рядку в браузері або натисніть Enter на порожньому склі, щоб вибрати файл. Копір друкує оригінал і кладе його на скло лицем донизу. Файл, покладений на скло, ніколи не запускає копіювання.","docs.copier.p2":"Натисніть зелену клавішу START або Ctrl+Enter (Cmd+Enter на Mac). Кришка закривається, лампа проходить, і копія виїжджає в лоток: аудіолуп виходить як MIDI, по сторінці на кожну партію, яку чує копір; MIDI-файл виходить як аудіо, по сторінці на партію. Esc або червона клавіша STOP скасовує копіювання; сіра клавіша HOME очищає скло.","docs.shot.copierStart.alt":"Копір із MIDI-файлом на склі: скло, на яке копір поклав надрукований оригінал лицем донизу, у червоній рамці з номером 1, сенсорний екран з номером 2 і зелена клавіша START з номером 3.","docs.shot.copierStart.caption":"Оригінал лежить на склі лицем донизу (1), екран показує, у який бік його буде скопійовано (2), а START (3) робить копію.","docs.copier.p3":"Кожна сторінка — це справжній файл у вашій теці «Копії» (Документи/Freally Flipcopy/Copies, якщо ви не виберете іншу в «Налаштуваннях»), з номером; він ніколи не переміщується, не перезаписується й не видаляється. Візьміть сторінку за лаймову рамку навколо її надрукованого кліпу й перетягніть просто на доріжку у вашій DAW — або перетягніть одразу всю стопку.","docs.shot.copierPages.alt":"Копір після копіювання MIDI-файлу в аудіо: його аудіосторінки лежать стосом у лотку, верхня сторінка в червоній рамці: візьміть сторінку за лаймову рамку навколо її надрукованого кліпу й перетягніть на доріжку.","docs.shot.copierPages.caption":"Копія в лотку: візьміть верхню сторінку за її лаймову рамку й перетягніть у DAW.","docs.copier.p4":"Звуки копіра тихо звучать через власний вихід плагіна — ніколи під час відтворення DAW і ніколи в bounce. Вимкніть або приглушіть їх у Налаштуваннях.","docs.copier.p5":"Апарат поводиться як справжній: він дає легкий поштовх, коли опускається кришка, м’яка тінь лягає там, де кожна копія вигинається, виходячи зі щілини, і кожна копія лежить під своїм невеликим кутом. «Налаштування → Анімація → Зменшити» прибирає поштовх.","docs.audioToMidi.p1":"Покладіть аудіолуп на скло й натисніть START: копір слухає його і друкує MIDI-сторінку для кожної партії, яку чує, у такому порядку: ударні, басова лінія, мелодія, контрмелодія та акорди. Партія, у якій він нічого не знаходить, сторінки не отримує, а луп, у якому взагалі немає нот, відхиляється — його ніколи не копіюють порожньою сторінкою.","docs.audioToMidi.p2":"Ударні записуються на ноти набору General MIDI — бочка, малий барабан, хети та інші, — тож грають на будь-якому драм-реку, а їхня сторінка друкує по рядку на кожен голос. Басова лінія, мелодія й контрмелодія — кожна однією лінією. Акорди записуються як прогресія — який акорд коли звучить, — а не як зігране розташування, і їхня сторінка так і каже: ПРОГРЕСІЯ - НЕ ЗІГРАНЕ РОЗТАШУВАННЯ. Тональність лупа сторінка друкує, лише якщо її прочитано однозначно.","docs.shot.audioParts.alt":"«Налаштування копіювання» відкрито над копіром, на склі аудіолуп, показано налаштування АУДІО > MIDI: «Партії» в червоній рамці з номером 1, «Сітка» з номером 2 і «Свінг» з номером 3.","docs.shot.audioParts.caption":"Для аудіолупа в «Налаштуваннях копіювання» вибираються «Партії» для копіювання (1), «Сітка», на яку стають ноти (2), і те, чи зберігається свінг (3).","docs.audioToMidi.p3":"Лінія вокалу — не одна з цих партій. Коли в «Партіях» вибрано «Кожна партія на окремій сторінці», копір чує вокал, залишає його як є і повідомляє про це на першій сторінці: ВОКАЛ ПОЧУТО Й ЗАЛИШЕНО ЯК Є. Щоб скопіювати сам вокал, виберіть «Партії» → «Вокальна лінія, по одній ноті»: лінія вокалу вийде однією MIDI-партією, по одній ноті. Луп, у якому немає нічого, крім лінії вокалу, під час копіювання всіх партій відхиляється, і екран пояснює чому.","docs.audioToMidi.p4":"Копір приймає лупи завдовжки до 16 тактів: він скопіює луп в один, два, чотири чи вісім тактів. Довший кліп відхиляється на склі із зазначенням його довжини й ніколи не обрізається, щоб уміститися. Так само відхиляється файл беззвучний, пошкоджений або такий, що не є аудіо, яке копір може прочитати.","docs.audioToMidi.p5":"Темп копії — той, у якому зіграно луп; він зчитується з аудіо, і сторінки друкують його з позначкою ПРОЧИТАНО. Темп вашого проєкту лише вирішує між двома прочитаннями одного й того самого лупа, наприклад 70 і 140 BPM; темпом копії він стає, лише коли в лупі ніщо не тримає ритм, і тоді сторінка так і каже. У самостійному застосунку те саме робить темп у назві файлу, наприклад Loop 90 BPM.wav, або 120, якщо в назві його немає. Натомість темп можна вибрати в «Налаштуваннях копіювання» → «Темп»: як у проєкті, з назви файлу або заданий вами.","docs.audioToMidi.p6":"Кожна сторінка — це файл, а файл можна скопіювати знову. Перетягніть аудіосторінку з лотка назад на скло або киньте її з «Копій» і натисніть START: її буде скопійовано назад у MIDI, а нова копія повідомить, з якої сторінки її зроблено. Оскільки кожна аудіосторінка закінчується на тактовій рисці, сторінка, прочитана назад, зберігає темп, у якому її записано.","docs.demo.roundTrip":"Туди й назад","docs.shot.audioPages.alt":"Копір після копіювання аудіолупа в MIDI: у лотку стос MIDI-сторінок, по одній на кожну почуту партію, верхня сторінка в червоній рамці.","docs.shot.audioPages.caption":"Аудіолуп, скопійований у MIDI: по сторінці на кожну партію, яку почув копір, — готові до перетягування.","docs.midiToAudio.p1":"Покладіть MIDI-файл на скло й натисніть START: копір програє кожну його партію через інструмент і друкує аудіосторінку для кожної партії — ударних, басової лінії, мелодії, контрмелодії та акордів, — як вони є у файлі. Разом зі сторінками виходить «Повний мікс» — усі партії, зіграні разом: перетягніть його за вкладку ПОВНИЙ МІКС унизу верхньої сторінки або всі сторінки одразу — за УСІ ПАРТІЇ. «Налаштування копіювання» → «Сторінки» → «Лише мікс» робить лише «Повний мікс».","docs.midiToAudio.p2":"Кожна мелодична партія грає через інструмент, який ви вибрали для неї в «Налаштуваннях копіювання» (Preview Piano, якщо ви не виберете інший), а ударні — через драм-машину: Preview Kit, тобто TR-909, якщо ви не виберете 808, 707, 606 або кіт із ваших власних ван-шотів. Кожна аудіосторінка друкує свій інструмент у рядку ТОНЕР. Пітч-бенд і педаль сустейну відтворюються; будь-який інший контролер у файлі зазначається на сторінці як невідрендерений і ніколи не відкидається мовчки.","docs.shot.midiPages.alt":"«Налаштування копіювання» з MIDI-файлом на склі, показано налаштування MIDI > АУДІО: «Сторінки» — сторінка на партію або лише мікс — у червоній рамці з номером 1, а інструмент мелодії з номером 2, між інструментами басової лінії й контрмелодії.","docs.shot.midiPages.caption":"Для MIDI-файлу в «Налаштуваннях копіювання» вибираються «Сторінки» (1) та інструмент, через який грає кожна партія (2).","docs.midiToAudio.p3":"«Хвіст» задає, як довго звук лунає після останньої ноти. Потім файл триває до наступної тактової риски у власному розмірі файлу, тож кожна аудіосторінка триває ціле число тактів: кинута у DAW, вона стає на сітку й чисто зациклюється, а свій темп несе для будь-якої DAW, яка його читає.","docs.midiToAudio.p4":"Кожна сторінка записується у WAV, AIFF, FLAC або MP3 (320 kbps) із частотою дискретизації проєкту або 44.1, 48, 88.2 чи 96 kHz, у 16- або 24-бітному вигляді чи в 32-бітному з рухомою комою. Якщо сторінка почала б перевантажуватися, копір приглушує її на фіксовану величину — рівно настільки, щоб вона лишалася нижче −0.3 dBFS, — і друкує це підсилення на сторінці. Він ніколи не застосовує лімітер і не нормалізує: тихий файл лишається тихим.","docs.shot.midiFormat.alt":"«Налаштування копіювання» нижче: драм-машина в червоній рамці з номером 1, повзунок «Хвіст» з номером 2, «Формат» із WAV, AIFF, FLAC і MP3 з номером 3, «Частота дискретизації» з номером 4 і «Розрядність» з номером 5.","docs.shot.midiFormat.caption":"Драм-машина (1), «Хвіст» (2) і те, як записуються сторінки: «Формат» (3), «Частота дискретизації» (4) і «Розрядність» (5).","docs.pages.p1":"Сторінка, усі ноти якої — ударні, друкує по рядку на кожен голос набору — бочка, малий барабан, закритий хет та інші — з назвами вашою мовою і в порядку Студії, замість рядка на кожну висоту. Барабан, для якого в наборі немає голосу, отримує власний рядок, названий за його нотою General MIDI.","docs.pages.p2":"Сторінки в лотку надруковано дрібно. Затримайте на одній із них вказівник, і за мить лупа покаже сторінку навколо вказівника, а дані стануть достатньо великими, щоб їх прочитати. Вона йде за вказівником, ніколи не з’являється, поки ви перетягуєте, і зникає, щойно ви натискаєте.","docs.screen.p1":"Екран копіра показує, що він робить і в який бік копіює: АУДІО > MIDI чи MIDI > АУДІО. Під ним — його програмні клавіші. ПАРАМЕТРИ відкриває «Налаштування копіювання»; ◀ НАЗАД і ДАЛІ ▶ гортають ваші копії; ЗБЕРЕГТИ, ПОКАЗАТИ і ПЕРЕДРУК працюють із копією в лотку. Жодна з них не запускає копіювання: це робить лише START.","docs.shot.screen.alt":"Сенсорний екран копіра після копіювання показує MIDI > АУДІО, а внизу — його програмні клавіші: ПАРАМЕТРИ в червоній рамці з номером 1, ЗБЕРЕГТИ з номером 2 і ПЕРЕДРУК з номером 3; між ними НАЗАД, ДАЛІ та ПОКАЗАТИ, а остання — СТУДІЯ.","docs.shot.screen.caption":"Програмні клавіші: ПАРАМЕТРИ (1) відкриває «Налаштування копіювання», ЗБЕРЕГТИ (2) зберігає верхню сторінку як новий файл, а ПЕРЕДРУК (3) повертає оригінал копії на скло.","docs.screen.p2":"Якщо MIDI-файл не має власного темпу, але його назва вказує темп — наприклад, Hook 127 BPM.mid, — біля екрана з’являється плашка, яка його пропонує. «Використати 127 BPM» копіює цей файл у цьому темпі; «Залишити темп проєкту» відхиляє пропозицію. Flipcopy ніколи не змінює темп вашої DAW, а кожна сторінка друкує свій темп і те, звідки він узявся.","docs.copySettings.p1":"Натисніть ПАРАМЕТРИ на сенсорному екрані — і з нього виросте панель. Кожне налаштування змінює копію, яку ви робите, а зміна стосується наступної копії, ніколи не тієї, що вже робиться; ваш проєкт їх зберігає. Tab переходить між елементами панелі, клавіші зі стрілками вибирають, а Esc закриває її.","docs.copySettings.p2":"Для аудіолупу пункт «Партії» визначає, що копіювати: кожну партію на окремій сторінці; лише одну партію — ударні, басову лінію, мелодію чи акорди; або вокальну лінію, по одній ноті. Якщо в лупі немає вибраної партії, копір так і каже, замість того щоб друкувати порожню сторінку. «Сітка» ставить ноти на 1/8, 1/16, 1/32 чи 1/16T або залишає їх такими, як їх прочитано, а «Свінг» зберігає свінг або вирівнює його.","docs.copySettings.p3":"Для MIDI-файлу пункт «Сторінки» дає сторінку на кожну партію або «Лише мікс», а «Хвіст» задає, як довго звук лунає після останньої ноти. «Формат» записує WAV, AIFF, FLAC або MP3 (320 kbps) із частотою дискретизації проєкту або 44.1, 48, 88.2 чи 96 kHz, у 16- або 24-бітному вигляді чи в 32-бітному з рухомою комою. FLAC і AIFF не мають рухомої коми, тож записуються у 24 біти; MP3 записується з частотою 44.1 або 48 kHz.","docs.copySettings.p4":"В обох напрямках «Темп» має варіанти «Автоматично», «Як у проєкті», «Власний темп файлу», «З назви файлу» і «Задати вручну».","docs.instruments.p1":"MIDI-копія програє кожну партію через інструмент із бібліотеки Freally — тієї самої, якою користується Freally MIDI Master. У «Налаштуваннях копіювання» почніть вводити текст у полі пошуку партії, щоб знайти інструмент за назвою, жанром чи родиною, додайте номер, щоб попросити одну з його варіацій, і виберіть його: басова лінія, мелодія, контрмелодія й акорди можуть мати кожна свій. За замовчуванням — Preview Piano. Ударні звучать через вибрану вами драм-машину: за замовчуванням Preview Kit, або 808, 707 чи 606.","docs.instruments.p2":"Кожна аудіосторінка друкує інструмент, на якому її зіграно, у рядку ТОНЕР поруч зі своїм темпом.","docs.copies.p1":"◀ НАЗАД і ДАЛІ ▶ на сенсорному екрані або клавіші [ і ] гортають усі зроблені вами копії; кожна лежить у лотку, готова до перетягування. ЗБЕРЕГТИ зберігає верхню сторінку як новий файл — куди ви захочете й у вибраному вами форматі. ПОКАЗАТИ показує копію в її теці. ПЕРЕДРУК повертає оригінал копії на скло з тими налаштуваннями, з якими її зроблено: натисніть START, щоб зробити її знову.","docs.copies.p2":"Перетягніть сторінку назад на скло або киньте її з «Копій» — і вона ляже як оригінал, готовий до копіювання у зворотний бік; нова копія повідомляє, з якої сторінки її зроблено. Щоб перетягнути кілька сторінок одразу, клацніть їх із Shift, а потім перетягніть одну: підуть усі, у порядку сторінок.","docs.copies.p3":"У теці кожної копії лежить ticket.txt — текстовий запис про те, як її зроблено: оригінал і його цифровий відбиток, налаштування, темп і звідки він узявся, інструменти, а також файл і цифровий відбиток кожної сторінки.","docs.studio.p1":"Над машиною дві вкладки: КОПІР і СТУДІЯ. Натисніть Ctrl+1 або Ctrl+2 (Cmd+1 або Cmd+2 на Mac), щоб перейти на них з будь-якого місця вікна, або переходьте між вкладками клавішами зі стрілками. Перемикання нічого не зупиняє: копія, яка сканується, і далі робиться за Студією, а її сторінки вже вийдуть, коли ви повернетеся. Кожен екземпляр плагіна пам’ятає свою вкладку.","docs.studio.p2":"Щоб відкрити копію, натисніть СТУДІЯ на сенсорному екрані — відкриється копія, що лежить у лотку, — або виберіть файл у «Копіях» у браузері й натисніть «Відкрити в Студії». Копія аудіолупа відкриває свої MIDI-сторінки, по вкладці партії на кожну, у порядку сторінок; копія MIDI-файлу відкриває партії MIDI, з якого її зроблено. Ноти читаються з файлів, які записала копія, тож копія, чиї файли переміщено або змінено, не відкриється, і Студія пояснить чому. Якщо у відкритій копії є ненадіслані зміни, Студія запитає, перш ніж відкрити іншу.","docs.shot.studio.alt":"Студія з відкритою копією: вкладка партії «Мелодія» в червоній рамці з номером 1, піано-рол з номером 2, «Відтворити» з номером 3 і «Надіслати до копіра» з номером 4.","docs.shot.studio.caption":"Виберіть партію (1), відредагуйте її ноти в піано-ролі (2), програйте її (3) і надішліть правку до копіра (4).","docs.studio.p3":"Кожна партія редагується в піано-ролі Freally MIDI Master. Двічі клацніть, щоб намалювати ноту, і перетягніть ноту, щоб зсунути її. Потягніть її лівий або правий край — там указівник перетворюється на [ або ], — щоб укоротити чи подовжити її. Виділяйте ноти рамкою, клацанням із Shift або клацанням з Ctrl; копіюйте, вирізайте й вставляйте їх; клонуйте їх поєднанням Shift+D або перетягуванням з Alt; видаляйте їх клавішею Delete, Backspace або клацанням правою кнопкою; і зсувайте їх клавішами зі стрілками.","docs.studio.p4":"Під нотами — доріжка сили натиску, а «Прив’язка» вибирає сітку, до якої прилипають ноти. Ctrl+Z скасовує, а Ctrl+Shift+Z або Ctrl+Y повторює (Cmd на Mac). Партія ударних показує голоси свого набору за назвами збоку. Щоб змінити партію, клацніть її вкладку або скористайтеся клавішами зі стрілками, Home і End, коли вкладка партії у фокусі.","docs.studio.p5":"«Відтворити», «Зупинити» і «Повтор» програють партії, а кожна партія має S, щоб увімкнути її соло, і M, щоб вимкнути її звук. Звучить саме той файл, який отримає копір, через інструменти, якими друкує копія, і партія в соло звучить саме так, як прозвучить її сторінка копії. Інструмент партії можна змінити просто там, а для ударних — і драм-машину.","docs.studio.p6":"«Надіслати до копіра» записує правку як новий MIDI-файл у теку Studio у вашій теці «Копії» — ніколи поверх іншого файлу, — кладе її на скло й показує копір. Нічого не копіюється, доки ви не натиснете зелену клавішу START; тоді правку копіюють як будь-який оригінал, а ticket.txt її копії повідомляє, з якої копії зроблено правку. Партія, яку ви спорожнили, не отримує сторінки, а правку без жодної ноти не надсилають: Студія пояснить чому. Якщо в правці лише одна партія, її файл названо за цією партією, наприклад Loop - Countermelody - Edit of copy 4 - 120 BPM.mid, щоб копір скопіював її як цю партію.","docs.mixer.p1":"Студія має три види — «Ноти», «Мікшер» і «Звук» — на вкладках у її правому верхньому куті; між ними переходять клавішами зі стрілками. Кожен фейдер, регулятор і вибір у них належить до «Налаштувань копіювання» проєкту, тож те, що грає Студія, — саме те, що друкує START, і все це зберігається разом із проєктом.","docs.mixer.p2":"У «Мікшері» є лінійка для кожної партії відкритої копії й одна для «Виходу». У кожної партії, крім ударних, це канальна лінійка Freally MIDI Master: «Низькі», «Середні» й «Високі», посили «Кімната» і «Відлуння», «Жар» і «Мод. висоти». Під нею — регулятор «Панорама», фейдер з вимірювачем рівня та клавіші S і M. Вимірювач зелений нижче −12 dBFS, жовтий до −3 і червоний вище, а його індикатор перевантаження загоряється на 0 dBFS і світиться, доки ви не клацнете його. Партія, у якої фейдер опущено до упору, взагалі не друкується.","docs.shot.mixer.alt":"«Мікшер» Студії — лінійка для кожної партії й одна для «Виходу»: фейдер лінійки мелодії в червоній рамці з номером 1, її регулятор панорами з номером 2 і її клавіша S, поруч із якою M, з номером 3.","docs.shot.mixer.caption":"Лінійка кожної партії: її фейдер (1), регулятор панорами (2) і S, щоб увімкнути соло (3), а поруч M, щоб вимкнути її звук.","docs.mixer.p3":"Перетягуйте фейдер або регулятор угору й униз, утримуйте Shift для точного налаштування або крутіть над ним коліщатко миші. Коли він у фокусі, клавіші зі стрілками зсувають його на крок, Home і End переводять його в одне чи друге крайнє положення, а подвійне клацання повертає його: фейдер — на 0 dB, регулятор — на його власне значення за замовчуванням. Кожен із них повідомляє своє значення, поки рухається.","docs.mixer.p4":"У «Звуці» ви формуєте звучання показаної партії. Вона звучить через інструмент бібліотеки, а під ним — сторінка SYNTH із Freally MIDI Master: осцилятори, саб і шум, фільтр, обидві обвідні, LFO, макроси й ефекти. Кожен регулятор, який ви повертаєте, зберігається разом із налаштуваннями копії, а «Скинути» повертає їх усі. Зірочка позначає інструмент як улюблений, а зі списку «Позначені» можна вибрати один із них, щоб партія зазвучала через нього.","docs.mixer.p5":"Ваші власні семпли беруться з браузера: виберіть аудіофайл і натисніть «Додати до ваших семплів». Семпл має бути файлом на цьому комп’ютері, аудіо тривалістю до 20 секунд; його висоту зчитують під час додавання, а сам семпл перевіряють знову щоразу, коли він звучить, тож семпл, який перемістили або змінили, ніколи не прозвучить як щось інше. «Новий звук семплера» грає один із ваших семплів по всій клавіатурі — з його основною нотою, підстроюванням, обвідною, фільтром і гучністю. Для ударних «Новий драм-кіт» збирає кіт із ваших ван-шотів: виберіть ван-шот для доріжки або перетягніть його з браузера на доріжку.","docs.mixer.p6":"Ваше обране, семпли, кіти й звуки семплера зберігаються в одній бібліотеці інструментів, спільній для всіх продуктів Freally на цьому комп’ютері. Flipcopy не постачається із семплами: ваші читаються там, де вони лежать.","docs.demo.ownSounds":"Ваші власні семпли","docs.browser.p1":"Браузер відкривається на своїх категоріях: «Копії» — усі сторінки й мікси, які ви зробили, і «Нещодавні» — оригінали, які ви востаннє клали на скло. Під ними — додані вами теки; виберіть «+ Додати теку», щоб додати ще одну, загалом до 128. Тека на диску, який не під’єднано, зберігає своє місце й повідомляє, що зараз не під’єднана. Щоб більше не переглядати теку, клацніть її правою кнопкою миші або виберіть її й натисніть Delete; на диску нічого не змінюється.","docs.browser.p2":"Відкрийте теку, щоб пройти її як дерево. Почніть друкувати, щоб відфільтрувати її за назвою, виберіть тег або «Позначені», щоб звузити список, і виберіть «Показувати всі файли», щоб побачити службові файли, які Flipcopy приховує, як-от .asd і .reapeaks. «Назад» і «Уперед» проводять вас місцями, де ви вже побували.","docs.shot.browser.alt":"Браузер відкрито на теці з музикою: поле фільтра в червоній рамці з номером 1, рядок вибраного MIDI-файлу з номером 2 і маркер у кінці цього рядка, який перетягує файл у DAW, з номером 3.","docs.shot.browser.caption":"Відфільтруйте теку за назвою (1), виберіть файл (2) і перетягніть його у DAW за маркер у кінці його рядка (3).","docs.browser.p3":"Пересувайтеся рядками клавішами ↑ і ↓: кожен рядок, на який ви потрапляєте, один раз звучить у попередньому прослуховуванні. → відкриває теку, а ← закриває її. Enter кладе вибраний файл на скло — так само, як подвійне клацання на ньому чи перетягування його рядка на копір.","docs.demo.doubleClick":"Подвійне клацання кладе файл на скло","docs.browser.p4":"Коли ви вперше додаєте теку, Flipcopy підраховує її файли, а смуга показує, наскільки він просунувся. Він читає не глибше 12 рівнів тек і не більше 50 000 файлів і ніколи не переходить за ярликом за межі теки.","docs.preview.p1":"Програвач попереднього прослуховування розташований під браузером. Аудіофайл показує свою справжню форму хвилі. MIDI-файл показує свої ноти й звучить через Preview Piano — той самий звук, що використовує копія, якщо ви не виберете інший, — тож ви чуєте, як звучатиме копія.","docs.preview.p2":"Пробіл запускає й призупиняє відтворення, «Зупинити» повертає на початок, а клацання чи перетягування по смузі переміщує курсор відтворення. «Повтор» повторює файл, «Відтворювати під час вибору» (навушники) програє кожен вибраний файл, а повзунок задає рівень. Попереднє прослуховування звучить через власний вихід Flipcopy і ніколи не потрапляє в bounce. WAV-файл будь-якої тривалості відтворюється; файл в іншому форматі — якщо він триває п’ять хвилин або менше.","docs.shot.preview.alt":"Програвач попереднього прослуховування відтворює MIDI-файл, його ноти намальовано на смузі: клавіша відтворення й паузи в червоній рамці з номером 1, «Повтор» з номером 2, «Відтворювати під час вибору» (навушники) з номером 3 і повзунок рівня з номером 4.","docs.shot.preview.caption":"Відтворення й пауза (1), «Повтор» (2), «Відтворювати під час вибору» (3) і рівень (4).","docs.preview.p3":"Клацніть оригінал на склі або сторінку в лотку, щоб його почути. Коли копія готова, «Копія» програє всі її сторінки разом, а «Оригінал» — файл на склі, з того самого місця в музиці, щоб ви почули різницю до перетягування. Слухати не обов’язково: сторінки можна перетягувати, щойно ляже остання.","docs.preview.p4":"Смуга має ту саму лаймову рамку, що й сторінка. Перетягніть її на скло, щоб покласти туди цей файл.","docs.daw.p1":"Flipcopy створено, щоб залишатися в проєкті: те, що лежить на його склі, зберігається разом із проєктом, він може відсканувати кілька тактів просто з доріжки, на якій стоїть, його браузер перетягує будь-який файл просто на доріжку, а в одному проєкті одночасно може працювати багато копірів.","docs.daw.saved.title":"Зберігається разом із проєктом","docs.daw.saved.p1":"Оригінал на склі зберігається разом із проєктом вашої DAW — із вибраними вами «Налаштуваннями копіювання». Відкрийте проєкт знову, і скло знову його покаже. Якщо файл відтоді перемістили, скло повідомить «Оригінал переміщено», а «Знайти…» допоможе його відшукати.","docs.daw.saved.p2":"Проєкт, стан Flipcopy в якому не вдається прочитати, відкривається з порожнім склом і повідомляє про це; нічого з іншого проєкту ніколи не переноситься. Налаштування, збережені новішою версією Flipcopy, зберігаються як є, тож якщо відкрити проєкт у старішій версії й знову зберегти, нічого не загубиться.","docs.daw.scan.title":"Скан із доріжки","docs.daw.scan.p1":"У DAW «Налаштування копіювання» мають «Скан із доріжки». Виберіть від 1 до 16 тактів, натисніть «Звести», потім натисніть відтворення у DAW. Поки доріжка грає, її звук — або MIDI-ноти, які вона отримує, — записується на вибрану кількість тактів, зберігається як новий файл у теці Captures у вашій теці «Копії» й кладеться на скло. Нічого не копіюється, доки ви не натиснете зелену клавішу START.","docs.daw.scan.p2":"Такти рахуються за темпом і розміром вашої DAW: якщо вона їх ще не передає, натисніть відтворення один раз, потім зведіть. Панель повідомляє, чого не передає хост. Ableton Live не дає аудіоефекту MIDI, тож там скан бере звук доріжки, а не її ноти; Logic може не відтворювати неактивну доріжку, тож перед сканом увімкніть на доріжці готовність до запису або запустіть її відтворення. Поки ваша DAW виконує bounce, нічого не сканується, а в окремому застосунку немає доріжки для скану: натомість покладіть файл на скло.","docs.daw.drag.title":"Перетягніть файл просто у свою DAW","docs.daw.drag.p1":"У кінці рядка кожного аудіо- та MIDI-файлу в браузері, а також на смузі попереднього прослуховування є маркер перетягування — «Перетягніть файл у DAW». Перетягніть його на доріжку, і туди ляже сам файл — точнісінько такий, який він на вашому диску. Сам рядок і далі можна перетягнути на скло, щоб скопіювати.","docs.daw.drag.p2":"Хай що ви перетягуєте у свою DAW — сторінку чи файл, — під указівником видно картинку саме цього кліпу: його ноти або форму хвилі, у лаймовій рамці. DAW, яка не малює картинку перетягування, показує натомість власний значок файлу; сам файл той самий.","docs.daw.instances.title":"Багато копірів одночасно","docs.daw.instances.p1":"Ставте Flipcopy на скільки завгодно доріжок: кожен копір має власне скло, власні «Налаштування копіювання» і власну вкладку. Вісім копірів одночасно — кожен зі своїми звуками, своїм попереднім прослуховуванням і запущеним сканом — займають значно менше одного відсотка буфера в 256 семплів, а вікно, у якому ніщо не рухається, взагалі не запускає анімацію.","docs.standalone.p1":"Самостійний застосунок — це весь Flipcopy у власному вікні: копір, браузер і попереднє прослуховування, «Налаштування копіювання» і Студія; звучить він через аудіовихід, вибраний у «Налаштуваннях». Єдине, чого в ньому немає, — «Скан із доріжки», якому потрібна доріжка DAW; натомість покладіть файл на скло. Це спосіб користуватися Flipcopy без DAW, поруч із нею або з DAW, яка не може завантажити плагін.","docs.standalone.p2":"Pro Tools завантажує лише плагіни AAX, а Flipcopy не має версії AAX, тож у Pro Tools він не з’являється. Натомість запустіть самостійний застосунок поруч із Pro Tools: перетягніть сторінку з лотка або файл із браузера за його маркер просто на доріжку Pro Tools. Якщо перетягування не спрацьовує, натисніть ЗБЕРЕГТИ на сенсорному екрані, збережіть сторінку будь-де й імпортуйте її в Pro Tools.","docs.settings.p0":"Відкрийте «Налаштування» через шестерню вгорі браузера. Розділи налаштувань перелічено збоку (Загальні, Вигляд, Звуки, Анімація, Аудіовихід, Тека «Копії», Про програму), а вибраний відкривається поруч.","docs.settings.p1":"«Звуки машини» вмикають або вимикають звуки копіра, задають їхній рівень і приглушують їх, поки грає ваша DAW. Окремий перемикач вимикає м’які звуки, які видають панелі й діалогові вікна, коли відкриваються та закриваються.","docs.settings.p2":"У розділі «Анімація» варіант «Швидка» запускає машину з короткими таймінгами, і кожен звук лишається на своєму місці. «Зменшення руху» слідує налаштуванню вашої системи — або виберіть «Зменшити», щоб воно діяло завжди: без перевертання, без хитання кришки, без проходу лампи й без затемнення кімнати. Копір і далі показує кожен крок і програє кожен звук, а START і далі єдиний спосіб зробити копію.","docs.settings.p3":"Тека «Копії» показує, куди потрапляють ваші копії. «Змінити…» вибирає іншу теку: нові копії потрапляють туди, а вже зроблені лишаються там, де є. «Показати в теці» відкриває її. «Про програму» показує версію, ліцензії третіх сторін і ліцензійну угоду.","docs.shot.settings.alt":"Налаштування відкрито на розділі Тека «Копії»: розділ у червоній рамці з номером 1 і «Змінити…», що вибирає іншу теку для нових копій, з номером 2.","docs.shot.settings.caption":"Відкрийте розділ Тека «Копії» (1), потім «Змінити…» (2), щоб вибрати, куди потрапляють нові копії.","docs.demo.sounds":"Звуки копіра і звуки анімацій","docs.demo.motion":"«Швидка» і «Зменшити»","docs.appearance.p1":"Flipcopy має темну й світлу теми, обидві в зеленому кольорі Freally. У «Налаштуваннях», у розділі «Вигляд», виберіть «Темна» або «Світла»: кожну з них показує власний копір. Зміна відбувається миттєво, без спалаху іншого кольору, і зберігається на цьому комп’ютері — однаково в плагіні та в окремому застосунку.","docs.shot.appearance.alt":"Налаштування відкрито на розділі «Вигляд»: «Темна», показана власним копіром, у червоній рамці з номером 1, і «Світла» з номером 2.","docs.shot.appearance.caption":"У розділі «Вигляд» виберіть «Темна» (1) або «Світла» (2).","docs.appearance.p2":"Копір відрендерено на власному тлі кожної теми, тож він завжди стоїть в одній кімнаті, без жодної підкладки навколо. Панелі, скло, діалогові вікна й клавіші взято з єдиного дизайну, спільного для всіх застосунків Freally, а регулятори, фейдери, повзунки, перемикачі й клавіші відрендерено для кожної теми. Рядок заголовка окремого застосунку теж слідує темі й не містить назви: заголовком слугує сама обертова назва.","docs.appearance.p3":"У розділі «Анімація» варіант «Зменшити» вирівнює обертовий заголовок: у режимі зменшеного руху — чи ви його вибрали, чи його вимагає система — заголовок зупиняється прямо перед вами, рівно й нерухомо. «Швидка» повертає його вдвічі швидше — так само, як прискорює й усе інше, а зменшення руху й далі має перевагу над обома швидкостями. У розділі «Звуки» перемикач «Звуки анімацій» вмикає або вимикає звуки відкриття й закриття діалогів і панелей — окремо від власних звуків копіра.","docs.trouble.p0":"Про більшість проблем повідомляє сенсорний екран копіра. Ось найпоширеніші з них і що робити з кожною.","docs.trouble.refused.title":"Файл відхилено","docs.trouble.refused.p1":"Екран називає причину. Копір приймає лупи до 16 тактів і відхиляє файл, який довший або більший, ніж він приймає, беззвучний, пошкоджений або не є аудіо чи MIDI, які він може прочитати. Він також відхиляє MIDI-файл без нот, із більшою кількістю нот, ніж він приймає, з відліком часу в кадрах SMPTE або з окремими піснями (формат 2), а також файл на мережевому ресурсі — його спершу треба скопіювати на цей комп’ютер. Укоротіть довгий луп до 16 тактів у DAW і покладіть на скло вже вкорочений.","docs.shot.refused.alt":"Сенсорний екран копіра в червоній рамці відхиляє задовгий луп, і по ньому біжить причина: Тактів у цьому кліпі: 32 — копір приймає кліпи до 16 тактів.","docs.shot.refused.caption":"Файл, який копір відхиляє: його екран пояснює чому.","docs.trouble.vocal.title":"Лінію вокалу залишено як є","docs.trouble.vocal.p1":"Коли в «Партіях» вибрано «Кожна партія на окремій сторінці», вокал чутно й залишено як є, а перша сторінка про це повідомляє. Щоб скопіювати лінію вокалу, виберіть у «Налаштуваннях копіювання» «Партії» → «Вокальна лінія, по одній ноті» і знову натисніть START.","docs.trouble.nothing.title":"Нічого не знайдено","docs.trouble.nothing.p1":"Коли екран повідомляє, що в кліпі нема чого копіювати, копір не знайшов у ньому нот. Якщо ви попросили лише одну партію, наприклад «Лише ударні», а в лупі її немає, екран так і каже, замість того щоб друкувати порожню сторінку: виберіть «Кожна партія на окремій сторінці» або іншу партію.","docs.trouble.start.title":"START нічого не робить","docs.trouble.start.p1":"START копіює те, що лежить на склі, тож спершу покладіть туди файл. Поки робиться копія, копір зайнятий: дочекайтеся її або натисніть STOP. Якщо файл на склі змінився або його перемістили після того, як ви його туди поклали, покладіть його на скло знову. Ctrl+Enter натискає START, лише коли показано вкладку КОПІР.","docs.trouble.daw.title":"Flipcopy немає в списку плагінів вашої DAW","docs.trouble.daw.p1":"Переконайтеся, що плагін лежить у теці, яку ваша DAW сканує в пошуках плагінів CLAP або VST3 (чи AU на Mac), а потім перескануйте плагіни в DAW. Logic перевіряє AU під час наступного запуску. Pro Tools ніколи не показує Flipcopy: див. «Самостійний застосунок і Pro Tools».","docs.trouble.drag.title":"Перетягування не доходить до DAW","docs.trouble.drag.p1":"Деякі хости не приймають файл, перетягнутий із вікна плагіна; коли Flipcopy може це визначити, його екран повідомляє: Тут перетягування недоступне — скористайтеся «Зберегти як». Натисніть ЗБЕРЕГТИ на сенсорному екрані, щоб зберегти верхню сторінку як новий файл — будь-де й у вибраному вами форматі, — а потім імпортуйте його; ПОКАЗАТИ показує власний файл копії в його теці. З клавіатури Tab теж доходить до «Зберегти копію як…» і «Показати копію в теці».","docs.report.p1":"Якщо збій стався в самому Flipcopy — наприклад, він не зміг записати копію, — екран пропонує «Повідомити». Відкриється сторінка у вашому веббраузері, яка показує, що саме містить звіт; нічого не надсилається, доки ви не натиснете там «Надіслати». Файл, який копір відхиляє, бо він задовгий, тихий або не є аудіо, — це не збій, і екран натомість пояснює причину.","docs.keys.p1":"Усі клавіші нижче працюють і в плагіні, і в самостійному застосунку. На Mac натискайте Cmd скрізь, де в таблиці вказано Ctrl. Поки ви друкуєте в полі — наприклад, у фільтрі чи в полі темпу, — клавіші вводять текст.","docs.keys.copier":"Копір","docs.keys.col.key":"Клавіша","docs.keys.col.does":"Що робить","docs.keys.start":"Натиснути START: скопіювати те, що лежить на склі.","docs.keys.stop":"Натиснути STOP, поки робиться копія.","docs.keys.choose":"На порожньому склі: вибрати файл, щоб покласти його на скло.","docs.keys.page":"Гортати ваші копії назад і вперед.","docs.keys.tray":"Дістатися до копії в лотку з клавіатури: «Зберегти копію як…», «Показати копію в теці», «Покласти верхню сторінку на скло» і «Прослухати верхню сторінку».","docs.keys.window":"Вікно","docs.keys.tabs":"Показати вкладку КОПІР або СТУДІЯ.","docs.keys.fold":"Згорнути браузер і попереднє прослуховування або повернути їх.","docs.keys.space":"Запустити або призупинити попереднє прослуховування.","docs.keys.close":"Закрити «Налаштування копіювання», «Налаштування» або відкритий список чи скасувати перетягування на скло.","docs.keys.splitter":"На лінії поруч із браузером: зробити браузер вужчим або ширшим чи відсунути його до одного з країв.","docs.keys.tablist":"На ряду вкладок або варіантів: перейти до наступного чи попереднього або до одного з країв.","docs.keys.browser":"Браузер","docs.keys.rows":"Перейти на рядок вище або нижче.","docs.keys.ends":"Перейти до першого або останнього рядка.","docs.keys.open":"Відкрити теку або зайти у відкриту.","docs.keys.closeFolder":"Закрити теку або піднятися до теки, у якій вона лежить.","docs.keys.place":"Покласти вибраний файл на скло; на теці — відкрити або закрити її.","docs.keys.filter":"Почати вводити назву, щоб відфільтрувати за нею теку.","docs.keys.remove":"На доданій вами теці: припинити її переглядати. На диску нічого не змінюється.","docs.keys.studio":"Піано-рол Студії","docs.keys.undo":"Скасувати.","docs.keys.redo":"Повторити.","docs.keys.selectAll":"Виділити всі ноти партії.","docs.keys.deselect":"Зняти виділення.","docs.keys.clipboard":"Копіювати, вирізати й вставляти виділені ноти; вставлені ноти лягають на курсор відтворення.","docs.keys.duplicate":"Дублювати виділені ноти на тому самому місці.","docs.keys.duplicateAfter":"Дублювати виділені ноти одразу після них самих.","docs.keys.delete":"Видалити виділені ноти.","docs.keys.nudge":"Зсунути виділені ноти на крок сітки раніше чи пізніше; із Shift — на цілий такт.","docs.keys.transpose":"Зсунути виділені ноти на півтон угору або вниз; із Shift — на октаву. У партії ударних вони переходять на голос набору вище або нижче.","docs.keys.stretch":"Розтягнути виділені ноти до подвійної довжини або стиснути їх до половини (* на цифровій клавіатурі).","docs.keys.controls":"Фейдери й регулятори","docs.keys.step":"Зсунути фейдер або регулятор у фокусі на один крок.","docs.keys.tenth":"Зсунути фейдер на десяту частину його ходу.","docs.keys.toEnds":"Перевести його в одне з крайніх положень.","docs.privacy.p1":"У Flipcopy немає ні облікового запису, ні телеметрії, а плагін і окремий застосунок узагалі не містять мережевого коду. Ваші файли та ваші копії ніколи не покидають ваш комп'ютер.","docs.privacy.p2":"Він не містить ШІ жодного роду: кожна копія створюється класичною, детермінованою обробкою сигналу, і перевірка збірки не пройде, якщо колись буде додано бібліотеку машинного навчання.","docs.privacy.p3":"Єдиний виняток — необов'язкова перевірка оновлень, і вона вимкнена, доки ви не скажете «так». Окремий застосунок питає один раз; у DAW це питання не ставиться ніколи, і під час запуску перевірка не виконується. Окрема невелика програма — не плагін і не застосунок — отримує через HTTPS один публічний файл: freallyproducts.com/freally-flipcopy/version.json. Вона не надсилає ні ідентифікатора, ні версії, ні будь-чого про ваш комп'ютер — лише те, що несе будь-який вебзапит: вашу IP-адресу. Якщо вийшла новіша версія, Flipcopy показує її опис і кнопку, яка відкриває цей сайт; він ніколи нічого не завантажує й не встановлює. «Налаштування → Оновлення» показують, коли була остання перевірка, і вмикають або вимикають її.","docs.demo.updates":"Перевірка оновлень","docs.build.p1":"Вихідний код Flipcopy закритий: його не публікують, публічного репозиторію немає, і сьогодні ніхто поза проєктом не може його зібрати.","docs.build.p2":"Для довідки: для збирання потрібні Rust stable — саме тієї версії, яку закріплює вихідний код, — і Node.js. <code>npm ci</code> встановлює інструменти редактора, а <code>npm run plugin:build</code> збирає редактор і плагін та копіює CLAP і VST3, а на Mac і AU, у ваші теки плагінів.","kit.skip":"Перейти до вмісту","kit.nav.site":"Сайт","kit.nav.home":"Головна","kit.nav.features":"Можливості","kit.nav.documentation":"Документація","kit.nav.changelog":"Журнал змін","kit.nav.language":"Мова","kit.nav.allApps":"Усі застосунки Freally","kit.badge.progress":"v1.0.0-beta готова · далі v1.0.0-rc","kit.cta.features":"Усі можливості","kit.cta.docs":"Читати документацію","kit.price":"Freally Flipcopy зараз безкоштовний, але може не залишитися безкоштовним назавжди: майбутні версії можуть продаватися.","kit.noDownloads":"Завантажень поки немає, а вихідний код закритий.","kit.label.overview":"Огляд","kit.label.inAction":"У дії","kit.label.inside":"Усередині","kit.label.roadmap":"Дорожня карта","kit.ladder.done":"Готово","kit.ladder.planned":"Заплановано","kit.ladder.goal":"Мета","kit.ladder.later":"Пізніше","kit.label.honesty":"Чесно","kit.family.label":"Родина Freally","kit.family.title":"<span class=\"hl-muted\">Одна родина.</span> <span class=\"hl-bright\">Десять застосунків.</span>","kit.cta.label":"Що змінилося","kit.cta.title":"<span class=\"hl-muted\">Кожна версія</span> <span class=\"hl-bright\">записана.</span>","kit.cta.lede":"У журналі змін перелічено все, що змінювалося в Freally Flipcopy, версія за версією, усіма вісімнадцятьма мовами.","kit.cta.changelog":"Читати журнал змін","kit.footer.thisApp":"Цей застосунок","kit.footer.family":"Родина Freally","kit.status.devVersion":"У розробці · v1.0.0-beta","kit.head.features":"<span class=\"hl-muted\">Усе, що воно вміє,</span> <span class=\"hl-bright\">у порівнянні.</span>","kit.label.numbers":"У цифрах","kit.numbers.lead":"Кожну цифру пораховано за самим застосунком. Нічого не оцінено на око і нічого не округлено в більший бік.","kit.label.free":"Зараз безкоштовно","kit.label.compare":"Порівняння","kit.label.principles":"Принципи","kit.label.limits":"Обмеження","kit.states.title":"Що означають стани","kit.states.done":"зібрана й позначена тегом, але не завантажується з цього сайту","kit.states.planned":"ще треба зробити","kit.states.goal":"версія, до якої веде цей шлях","kit.states.later":"потім, і ще не заплановано","kit.states.ladder":"Переглянути всі щаблі шляху","kit.head.documentation":"<span class=\"hl-muted\">Як це працює,</span> <span class=\"hl-bright\">крок за кроком.</span>","kit.search.placeholder":"Пошук у документації","kit.docs.contents":"Зміст","kit.head.changelog":"<span class=\"hl-muted\">Кожна зміна,</span> <span class=\"hl-bright\">версія за версією.</span>","kit.changelog.lede":"Спочатку нове: усе, що змінювалося в Freally Flipcopy, кожною мовою цього сайту.","kit.changelog.versions":"Версії","kit.search.none":"На цьому сайті немає нічого, що відповідає запиту.","kit.zoom.close":"Закрити","changelog.b459f6095def":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0-beta</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Бета: зміцнення</span>","changelog.af3a7d02ce5b":"Кожна копія працює в обидва боки, кожен крайній випадок, з яким продукт обіцяє впоратися, має тест, збій зриває одну копію і ніколи — вікно, а Flipcopy тепер може повідомити вас про вихід нової версії, якщо ви його про це попросите.","changelog.6b02e0d363a4":"Додано","changelog.024770404130":"<strong>Туди й назад.</strong> Відрендерте MIDI-файл в аудіо, перетягніть аудіосторінку назад на скло й натисніть START: MIDI повертається у власному темпі. Відрендерена сторінка тепер закінчується на наступній тактовій рисці, тож рендер на 16 тактів знову лягає на скло, а не відхиляється як 17-тактовий.","changelog.ed89635b5fe6":"<strong>Вокальна лінія</strong> в розділі <em>Партії</em> налаштувань копіювання друкує проспівану партію на одній сторінці.","changelog.36b1bfb9b15f":"<strong>Необов'язкова перевірка оновлень, вимкнена, доки ви не скажете «так».</strong> Окремий застосунок питає один раз, після ліцензійної угоди; у DAW це питання не ставиться ніколи, і під час відкриття перевірка не виконується. <em>Налаштування → Оновлення</em> перевіряє, коли ви натискаєте <em>Перевірити оновлення</em>, показує, коли перевірка була востаннє, і вмикає або вимикає перевірку під час запуску. Окрема невелика програма, <code>flipcopy-updater</code>, читає через HTTPS один публічний файл і нічого не надсилає про вас. Якщо вийшла новіша версія, Flipcopy показує її опис простим текстом, а <em>Отримати</em> відкриває сторінку продукту. Нічого не завантажується й не встановлюється. Плагін і окремий застосунок, як і раніше, не містять мережевого коду.","changelog.e4cd61c774b9":"<strong>Інсталятори.</strong> Для Windows є програма встановлення (окремий застосунок із пунктом у меню «Пуск», VST3 і CLAP, а також програма видалення, яка прибирає рівно те, що встановила, і ніколи — ваші копії чи налаштування). Для Linux є <code>install.sh</code> і <code>uninstall.sh</code> — для вас або, з <code>--system</code>, для всіх. Пакет для macOS написано, і він чекає на Mac, на якому його зберуть.","changelog.d6b2b21aaa5d":"<strong>Посібник завершено.</strong> Кожен розділ сайту документації, з підписаними знімками екрана, усіма 18 мовами.","changelog.2a6141e43be0":"Змінено","changelog.0006eba558ef":"<strong>Сторінка ударних, прочитана назад, зберігає малий барабан.</strong> Малий барабан або бочка, зіграні разом із хай-хетом, тепер читаються як обидва удари, бочка рахується один раз, а дзвінкий хвіст бочки більше не читається як друга бочка. Згенерований барабанний луп тепер повертається з кожною бочкою, малим барабаном і хай-хетом; шлях туди й назад справжнього барабанного лупу тепер зберігає 83 % його ударів замість 72 %.","changelog.3585429713e3":"<strong>Ліцензійна угода тепер версії 2</strong>: у ній описано необов'язкову перевірку оновлень, і вас один раз попросять прийняти її знову.","changelog.57942db9a760":"Кадр, який апарат малює із запізненням, більше його не сповільнює: анімація копіра наздоганяє повільний кадр, а не відстає від нього.","changelog.965dabecb34c":"<strong>У macOS і Linux заголовок стоїть нерухомо</strong>, обличчям до вас, як за Зменшення руху. Їхні webview не можуть обертати його в 3D на відеокарті, і, обертаючись, він тримав усе вікно приблизно на 12 кадрах за секунду; нерухомим вікно малює 60. У Windows він обертається, як і раніше.","changelog.1246fc93bca0":"Виправлено","changelog.ac4b6a1e32ad":"<strong>START після перетягування сторінки назад більше не просто відкриває кришку знову.</strong> Якщо перетягнути відрендерену аудіосторінку назад на скло й натиснути START, кришка закривалася й знову відкривалася, а копія не створювалася. Фортепіано, «розігріте» попереднім прослуховуванням на одній частоті дискретизації, фальшиво грало наступну копію, зроблену на іншій. Потім мелодію сторінки сприймали за вокал, а її неціла довжина читалася в неправильному темпі. У плагіні була та сама помилка. Усе виправлено, і копія створюється.","changelog.d68aa27e15df":"Файл, кинутий на скло одразу після іншого, міг бути замінений попереднім або залишити скло порожнім. Тепер кинутий файл лягає на скло щоразу.","changelog.86fc5c10f24c":"Файл, який Flipcopy не може прочитати, тепер показує у своєму рядку в браузері попереджувальний знак із поясненням причини.","changelog.9b516168740e":"Сторінка, відрендерена з MIDI-файлу в непарному розмірі (7/8, 5/8, 7/16…), тепер повідомляє DAW свою справжню довжину в долях, тож грає в темпі файлу. Вона закінчується на першій тактовій рисці, яка припадає й на цілу долю.","changelog.f152da02e637":"Файл, звук якого тягнеться ще довго після останнього удару, більше не потрапляє на скло понад межу в 16 тактів.","changelog.52d17f42195f":"Смуга попереднього прослуховування називає інструмент, через який звучить MIDI-файл, — для файлу ударних це його набір, а не <em>Preview Piano</em>.","changelog.74edb79e8b6c":"Збій під час запису відсканованого дубля тепер зриває лише цей дубль, а наступний працює.","changelog.5f61489a6f5d":"У macOS і Linux клавіші сенсорного екрана показують, на якій із них перебуває клавіатура: клавіша у фокусі підсвічена й обведена просто на екрані.","changelog.4afab12e90bf":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">Точність, реалістичність і продуктивність</span>","changelog.3b258346a600":"Копії стали ближчими до того, що було зіграно, апарат і виглядає, і відчувається більше як справжній, кожна копія йде на повній швидкості комп’ютера, а кожен тип файлів, який читає Flipcopy, випробувано на його пошкоджених, випадкових і ворожих версіях.","changelog.1d54cae34c37":"<strong>Ударні друкуються на підписаних доріжках.</strong> Сторінка, усі ноти якої — ударні, друкує по рядку на кожен голос набору — бочка, малий барабан, закритий хет… — з назвами вашою мовою і в порядку набору в Студії, замість тридцяти з гаком рядків висот. Барабан, для якого в наборі немає голосу, отримує власний рядок, названий за його нотою General MIDI. Сторінка, де є бодай одна звуковисотна нота, зберігає рядки висот.","changelog.cda06b1bdac7":"<strong>Сторінка великим планом.</strong> Затримайте вказівник на сторінці в лотку — і лупа покаже сторінку навколо нього, а її дані будуть достатньо великими, щоб їх прочитати за будь-якого розміру вікна. Вона ніколи не заважає: її немає, поки ви перетягуєте, і вона зникає, щойно ви натискаєте.","changelog.732164d2a729":"<strong>Апарат став відчутним.</strong> Копір дає легкий поштовх, коли опускається кришка (якщо ввімкнено <em>Зменшення руху</em>, його немає), м’яка тінь лягає там, де кожна копія вигинається, виходячи зі щілини, і кожна копія лягає зі своїм легким перекосом.","changelog.52ddae978c5b":"<strong>Аудіо → MIDI точніше читає те, що було зіграно:</strong>","changelog.640e02623b3e":"Фортепіанна лінія — відрендерена, а потім прочитана назад — тепер повертається нота в ноту (96 % нот замість 11 %): обертони низької ноти більше не сприймаються як друга мелодія.","changelog.3ad2e4d08aab":"Повторно взята нота — це дві ноти, а вібрато більше не дробить одну ноту на кілька.","changelog.27ce3d3b084e":"Акорд тримається, доки не зіграно інший, тож витриманий акорд більше не зникає між тактами (основні тони акордів клавішної партії — 50 % → 75 % її тактів; партії мідних духових — 63 % → 75 %).","changelog.ed3abd250720":"Вокальна лінія позбулася зривів на обертони й уривків: 99 % нот провідного вокалу тепер потрапляють у його тональність (було 93 %).","changelog.562c9c8e1291":"Лінія флейти, прочитана назад: 94 % нот, а раніше — жодної.","changelog.4bad2257668c":"<strong>Кожна копія на повній швидкості.</strong> У Windows копіювання йшло до чотирьох разів повільніше, коли вікно Flipcopy було за іншим вікном; більше такого немає. MIDI → аудіо рендерить партії паралельно: 8-тактовий луп ударних — приблизно за 0.4 с, щойно його звуки завантажено.","changelog.26c0ec473955":"Світло апарата скрізь одного кольору: сяйво лампи, світло, що пробивається навколо кришки, і край скла.","changelog.10536aa32355":"Проєкт, чий збережений стан Flipcopy містив зайве поле, більше не відкривається з повідомленням, що його стан не вдалося прочитати.","changelog.72a72e839ffe":"Вручну відредагований файл бібліотеки більше не може підсунути теги, які Flipcopy відхилив би (порожні, задовгі, з керівними символами або понад 16 на одному файлі).","changelog.2047659c2639":"Запис копії, вручну змінений так, щоб називати більше сторінок, ніж друкує копія, пропускається й ніколи не показується.","changelog.b2cc16d94b92":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-17\">2026-10-17</time></span><span class=\"release__title\">Окремий застосунок, macOS і Linux</span>","changelog.4ed51e7648f7":"Окремий застосунок самостійно робить усе, що й плагін: лише одне вікно водночас, відкривається там, де ви його залишили, звучить через вибраний вами вихід, а файл, відкритий за його допомогою, одразу лягає на скло. Flipcopy перевірено в рушії, яким його малюють macOS і Linux, а налаштування тепер відкриваються розділами.","changelog.114aa4018af8":"<strong>Лише один окремий застосунок водночас.</strong> Повторний запуск Flipcopy виводить уже відкрите вікно на передній план замість того, щоб відкрити друге.","changelog.2e284faae100":"<strong>Вікно повертається туди, де ви його залишили</strong> — з тим самим розташуванням, розміром і станом розгортання — і лише на екран, який досі під’єднано.","changelog.9c78e20f68f4":"<strong>Виберіть аудіовихід.</strong> <em>Налаштування → Аудіовихід</em> показує ваші пристрої після пункту <em>Системне за замовчуванням</em>; вибір набуде чинності під час наступного запуску Flipcopy. Пристрій, якого вже немає, і далі названо, а звучить системне за замовчуванням. У DAW звуком керує DAW, і цей розділ не показано.","changelog.a9d2c9eefa39":"<strong>Відкрийте файл за допомогою Flipcopy.</strong> <em>Відкрити за допомогою</em> у Провіднику, подвійне клацання, щойно Flipcopy стане програмою для цього файлу, або файл, кинутий на значок Flipcopy: файл лягає на скло, готовий до START. Якщо Flipcopy вже відкрито, це вікно виходить на передній план і бере файл.","changelog.991294d43dec":"<strong>Двічі клацніть файл у браузері</strong>, щоб покласти його на скло, — так само, як <code>Enter</code>.","changelog.3d84696df63b":"<strong>Самоперевірка.</strong> <code>freally-flipcopy --self-test &lt;clip&gt;</code> копіює файл без вікна й без аудіопристрою, читає кожну сторінку назад із диска й завершується з помилкою, якщо щось не так.","changelog.62ea5e547240":"<strong>Налаштування відкриваються розділами.</strong> Розділи (Загальні, Вигляд, Звуки, Анімація, Аудіовихід в окремому застосунку, Тека «Копії», Про програму) перелічено збоку, а вибраний відкривається поруч, тож нічого не треба прокручувати.","changelog.37b2783764d4":"<strong>macOS і Linux:</strong> вікно Flipcopy тепер тестується у WebKit — рушії редакторів у macOS і Linux, — а також у тому рушії, яким користується Windows.","changelog.72810da5590a":"<strong>У Linux рекомендовано окремий застосунок</strong> скрізь, де вікно плагіна в хості працює неправильно: він робить усе, що й плагін, окрім <em>Скан із доріжки</em>.","changelog.47c108a7cbb5":"<strong>На повільному комп’ютері копір не відстає від своїх звуків.</strong> Коли кадрів на секунду було лише кілька, машина відставала від звуків, які сама ж відтворювала.","changelog.f7e5955622bf":"<strong>Акустичні фортепіано звучать правдивіше.</strong> Кожна нота звучить довше, як у справжнього інструмента (найдовше в рояля), а яскраве деренчання удару згасає разом із нотою, а не тягнеться через усю ноту. Дуже короткі ноти глушаться. Так звучить кожна копія, надрукована з акустичним фортепіано, і передрук старішої теж; файл, що вже лежить у вашій теці «Копії», ніколи не змінюється, а класичні фортепіано лишилися незмінними.","changelog.6d6f7c04c2b9":"Регулятор однаковий в обох темах — зі шліфованого срібла.","changelog.de9609b5d84e":"<strong>Файл, перетягнутий із Провідника на відкритий окремий застосунок, потрапляє на скло.</strong> З поточним середовищем виконання WebView2 webview сам приймав скинутий файл, і той так і не доходив.","changelog.e58dd70b9634":"<strong>У Linux без апаратного прискорення — на старому ноутбуці, у віртуальній машині, без драйвера GPU — копір малює сторінки потрібного розміру.</strong> Webview там не міг намалювати їх у перспективі, тож оригінал виглядав маленькою перекошеною карткою на склі, а копія — вузькою смужкою в лотку; тепер Flipcopy малює їх сам.","changelog.24f1d9b62b67":"<strong>DAW, яка закриває Flipcopy, поки браузер ще рахує вміст великої теки, більше не падає</strong> у Windows: Flipcopy лишається завантаженим до виходу з DAW, тож його фонова робота завжди доходить до кінця.","changelog.b4f4a49ef5c2":"<strong>Друге перетягування з браузера доходить до скла в macOS і Linux.</strong> Перетягування могло виділити текст, над яким проходило, і наступне перетягування тоді починалося всередині цього виділення й так і не доходило до скла.","changelog.476242cb7321":"<strong>«Freally Flipcopy уже відкрито»</strong> тепер і в Windows показується мовою вашої системи, як і решта вікна.","changelog.62133f39387e":"<strong>Завислий аудіодрайвер не може заморозити вікно:</strong> <em>Налаштування → Аудіовихід</em> чекає на список пристроїв щонайбільше дві секунди.","changelog.9e06846ba2df":"Відомі проблеми","changelog.5219a0fa3caf":"Finder у macOS поки що не передає Flipcopy файл, який відкриває; натомість кладіть його на скло з власного браузера Flipcopy.","changelog.0c25f40df598":"У macOS вікно окремого застосунку може відкриватися по центру, а не там, де ви його залишили; це буде перевірено на Mac до <code>v1.0.0</code>.","changelog.ad1079ac0447":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-09\">2026-10-09</time></span><span class=\"release__title\">У кожній DAW</span>","changelog.8e143766c735":"Flipcopy поводиться у вашій DAW як вихований плагін. Проєкт пам’ятає, що лежало на склі. Скануйте кілька тактів просто з доріжки, на якій стоїть копір. Перетягуйте файл із браузера просто на доріжку. Вісім копірів одночасно з буфером у 256 семплів ніколи не тріщать.","changelog.ce12abba882c":"<strong>Зберігається разом із проєктом.</strong> Оригінал на склі зберігається разом із проєктом вашої DAW, і скло показує його знову, щойно ви відкриєте проєкт. Якщо файл перемістили, скло повідомляє <em>Оригінал переміщено</em> і пропонує <strong>Знайти…</strong>, щоб його відшукати. Проєкт, стан Flipcopy в якому не вдається прочитати, відкривається з порожнім склом і повідомляє про це; нічого з попереднього проєкту ніколи не переноситься. Налаштування новішої версії Flipcopy в проєкті зберігаються як є, тож якщо відкрити проєкт у старішій версії й знову зберегти, нічого не загубиться.","changelog.fd7b1afa3b01":"<strong>Скан із доріжки.</strong> У DAW «Налаштування копіювання» мають <em>Скан із доріжки</em>: виберіть від 1 до 16 тактів, натисніть <strong>Звести</strong> й запустіть відтворення у DAW. Звук доріжки — або ноти, які вона отримує, — захоплюється під час відтворення, записується як новий файл у теку <code>Captures</code> вашої теки «Копії» й кладеться на скло. Нічого не копіюється, доки ви не натиснете START. Панель повідомляє, чого не передає хост: Ableton Live не дає аудіоефекту MIDI, а Logic може не відтворювати неактивну доріжку.","changelog.222f72339df2":"<strong>Перетягніть файл просто у свою DAW.</strong> Маркер у кінці рядка кожного аудіо- та MIDI-файлу в браузері, а також на смузі попереднього прослуховування перетягує на доріжку сам файл. Сам рядок і далі перетягується на скло.","changelog.38dd0a51f105":"<strong>Під час перетягування видно саме цей кліп.</strong> Поки сторінку чи файл перетягують у DAW, під курсором видно картинку цього кліпу — його ноти або форму хвилі — у лаймовій рамці.","changelog.4349d2ea9d2d":"<strong>Фортепіано звучать як фортепіано.</strong> Фортепіано Grand, Acoustic, Upright і Honky-Tonk — зокрема тонер за замовчуванням — грають новим акустичним голосом Freally MIDI Master, побудованим за вимірами записаного концертного рояля й піаніно, без деренчання. Копія, яку ви зробили раніше, зберігає фортепіано, з яким її було зроблено: «Передрук» і її квиток роблять її знову точно такою, якою вона була.","changelog.4dbfe3c38777":"<strong>Копія фортепіано, скопійована назад у MIDI, поки що читається гірше.</strong> Нові фортепіано звучать зі справжніми обертонами, і копір може почути їх як окрему лінію: сторінка мелодії може вийти на октаву чи більше вище, а справжні ноти опиняться на сторінці контрмелодії. Інші інструменти читаються як раніше. В одній із наступних версій копір навчиться відрізняти ноту від її обертонів.","changelog.528ac7aef2bf":"<strong>Вісім копірів одночасно.</strong> Вісім екземплярів, кожен зі своїми звуками, своїм попереднім прослуховуванням і запущеним сканом, займають значно менше одного відсотка блоку в 256 семплів; редактор, у якому ніщо не рухається, не запускає циклу анімації.","changelog.c5bb4099ef7c":"<strong>Клавіші зі стрілками й коліщатко миші зсувають фейдер на один крок — із Shift чи без.</strong> Фейдер тримає значення з точністю до десятої частки децибела; Shift і далі робить перетягування точнішим.","changelog.489f105e939c":"<strong>Два вікна Flipcopy, відкриті одночасно, відкриваються обидва.</strong> Коли їх відкривали разом — два окремі застосунки або в DAW, яка запускає кожен плагін в окремому процесі й відновлює їхні вікна, — редактор міг лишитися порожнім. Виправлено у webview, спільному для застосунків Freally.","changelog.047de85cd8a2":"<strong>Жодного клацання, коли DAW змінює частоту дискретизації чи розмір буфера</strong> під час попереднього прослуховування: звук повертається з того самого місця, плавно наростаючи за п’ять мілісекунд.","changelog.ea5df30e60e0":"Пошук інструмента й будь-який інший запит вікна до плагіна обмежено за розміром; надто великий запит відхиляється непрочитаним.","changelog.598233edd80f":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.9</span><time class=\"release__date\" datetime=\"2026-10-09\">2026-10-09</time></span><span class=\"release__title\">Світла тема</span>","changelog.ee349e4aa239":"Світла тема поруч із темною, обидві в зеленому кольорі Freally, — і один стиль, один набір відрендереного обладнання для всіх застосунків Freally.","changelog.e47c7e599a1f":"<strong>Світла й темна теми.</strong> <em>Налаштування → Вигляд</em>: «Темна» або «Світла», кожну показує власний копір. Зміна миттєва, без спалаху іншого кольору, і зберігається на цьому комп’ютері — однаково в плагіні та в окремому застосунку. Копір відрендерено на власному тлі кожної теми, тож він завжди стоїть в одній кімнаті, без жодної підкладки навколо.","changelog.b936af04b352":"<strong>Стиль Freally.</strong> Панелі, скло, діалогові вікна й клавіші взято з єдиного дизайну, спільного для всіх застосунків Freally, — сучасного, витонченого й футуристичного, у світлій і в темній темі, — а регулятори, фейдери, повзунки, перемикачі й клавіші відрендерено для кожної теми.","changelog.8d9fb3f2fece":"<strong>Рядок заголовка слідує темі.</strong> Рядок заголовка окремого застосунку світлий у світлій темі й темний у темній, без назви (заголовком слугує обертова назва).","changelog.58c3153a8c37":"<strong>«Зменшити» вирівнює заголовок.</strong> У режимі зменшеного руху — за власним налаштуванням Flipcopy чи за налаштуванням вашої системи — обертовий заголовок зупиняється прямо перед вами, рівно й пласко, а не застигає під кутом.","changelog.930a82a2f066":"<strong>«Швидка» обертає заголовок швидше</strong>: удвічі швидше, як і все, що прискорює «Швидка». Зменшення руху й далі має перевагу над обома швидкостями.","changelog.9a34338f7069":"<strong>Усі клавіші однакової ширини</strong> — кожною мовою, а написи, задовгі для неї, стали коротшими.","changelog.11bbf02df3a2":"<strong>Відтворення, зупинка й повтор у Студії — звичайні кнопки</strong>, як на панелі транспорту.","changelog.27a86b95b65b":"<strong>Розділ «Налаштування → Звуки» пояснює, що робить його перемикач</strong>: <em>Звуки анімацій</em> — звуки відкриття й закриття діалогів і панелей — можна ввімкнути чи вимкнути, окремо від власних звуків машини.","changelog.32a3454bd7d7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.7</span><time class=\"release__date\" datetime=\"2026-10-06\">2026-10-06</time></span><span class=\"release__title\">Мікшер і ваші власні інструменти</span>","changelog.17791d5cece3":"Студія отримує мікшер і звук для кожної партії. Зводьте партії реалістичними фейдерами й регуляторами, формуйте кожен інструмент синтезаторними регуляторами Freally MIDI Master і грайте партії через власні семпли — драм-кіт із ваших ван-шотів або один семпл по всій клавіатурі, — що зберігаються в одній бібліотеці інструментів, спільній для всіх продуктів Freally на вашому комп’ютері.","changelog.79b010c66ef4":"<strong>Ноти, Мікшер і Звук.</strong> Три види в Студії, поруч один з одним у її верхній частині; між ними переходять клавішами зі стрілками.","changelog.e333eccd6937":"<strong>Мікшер.</strong> Лінійка для кожної партії й одна для «Виходу»: фейдер з вимірювачем рівня, панорама, соло й вимкнення звуку, а для партії на інструменті бібліотеки — канальна лінійка MIDI Master: «Низькі», «Середні» й «Високі», «Кімната», «Відлуння», «Жар» і, для співучого інструмента, «Мод. висоти». Вимірювач світиться зеленим, від −12 dBFS — жовтим, від −3 — червоним, а його індикатор перевантаження загоряється на 0 dBFS і світиться, доки ви не клацнете його. Мікшер належить копії: те, що грає Студія, — це те, що друкує START, а партія з фейдером, опущеним до упору, не друкується.","changelog.1e76a79a1d7a":"<strong>Реалістичні фейдери, регулятори й клавіші.</strong> Відрендерені в Blender для всіх продуктів Freally: фейдери, кожен регулятор, командні клавіші й клавіші-перемикачі, з анімацією натискання (у режимі зменшеного руху натискання лишається, але без світіння). Перетягуйте, утримуйте Shift для точного налаштування, крутіть коліщатко миші, двічі клацніть, щоб повернути значення за замовчуванням, або користуйтеся клавіатурою; кожен повідомляє своє значення.","changelog.a3541ed53ef6":"<strong>Реалістичні повзунки й перемикачі увімк/вимк.</strong> Кожен повзунок має сіру рифлену ручку на жолобку, підсвіченому до неї, а кожне налаштування «увімк/вимк» стало перемикачем-пігулкою — він світиться, коли увімкнений, його ручка зсунута до цього краю, а в ньому видавлено УВІМК або ВИМК. Відрендерені в Blender разом із фейдерами, для темної та світлої теми.","changelog.09c5e76649f5":"<strong>Кожна кнопка — відрендерена клавіша.</strong> Налаштування, ліцензійна угода, браузер і студія використовують ті самі клавіші з Blender, що й копір, разом із їхнім натисканням, а клавіші поруч мають однакову ширину.","changelog.1f83f75b3bdd":"<strong>Звук партії.</strong> Інструмент бібліотеки зі сторінкою SYNTH із Freally MIDI Master — осцилятори, саб і шум, фільтр, обидві обвідні, LFO, макроси й ефекти, — що зберігається разом із налаштуваннями копії; «Скинути» повертає все як було.","changelog.e93b9221b8bd":"<strong>Ваші власні семпли.</strong> Виберіть аудіофайл у браузері й натисніть <em>Додати до ваших семплів</em>. Семпл — це файл на цьому комп’ютері тривалістю до 20 секунд; його висоту зчитують під час додавання, і його перевіряють знову щоразу, коли він звучить, тож семпл, який перемістили або змінили, ніколи не прозвучить як щось інше.","changelog.8f95a81b18c2":"<strong>Ваш власний драм-кіт.</strong> <em>Новий драм-кіт</em>, потім ван-шот на кожну доріжку — з ваших семплів або перетягнутий із браузера на доріжку.","changelog.4f44482071a3":"<strong>Простий семплер.</strong> Один із ваших семплів по всій клавіатурі для партії — з основною нотою, підстроюванням, обвідною, фільтром і гучністю.","changelog.26e0f4686505":"<strong>Обране.</strong> Зірочка на будь-якому інструменті, драм-машині, семплі, кіті чи звуці семплера; зі списку <em>Позначені</em> можна вибрати один із них для партії.","changelog.d16f22a46ceb":"<strong>Одна бібліотека інструментів для всіх продуктів Freally</strong> на цьому комп’ютері. Flipcopy не постачається із семплами: ваші читаються там, де вони лежать.","changelog.09f42e7fbf57":"<strong>Налаштування копіювання показують, що грає копія</strong>: партію на одному з ваших звуків семплера, ударні на вашому кіті й мікшер, налаштований у Студії, — з кнопкою для його скидання.","changelog.30e9ac21e3ee":"Вибраний для партії інструмент запускається таким, яким він є: регулятори, які раніше крутили на цьому інструменті, і звук семплера скидаються.","changelog.64c277607a3c":"<strong>Хвильові форми із самого звуку.</strong> Хвильова форма прев’ю — і картинка, яку файл несе під час перетягування, — читається з власних семплів файлу: кожен стовпчик має свої справжні піки й гучність і малюється так, як малює DAW: піки — м’яким контуром навколо щільного тіла. Короткий ван-шот раніше малювався кількома пласкими блоками.","changelog.df0a41720e80":"<strong>Розгорнуте вікно заповнене.</strong> Після розгортання чи збільшення автономний застосунок показував інтерфейс у розмірі, з яким відкрився, із білою смугою збоку; тепер усе вікно — це застосунок, масштабований цілком.","changelog.b75b41a222c5":"В арабській версії клавіша НАДІСЛАТИ ДО КОПІРА в Студії знову стоїть у кінці свого ряду.","changelog.2e81a71b3108":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.5</span><time class=\"release__date\" datetime=\"2026-10-06\">2026-10-06</time></span><span class=\"release__title\">Студія</span>","changelog.8b3ee24a5a5b":"Друга вкладка поруч із копіром. Відкрийте копію в <strong>Студії</strong>, і кожна її партія стане вкладкою в піано-ролі самого MIDI Master: змінюйте ноти, слухайте їх через інструменти, якими друкує копія, і надсилайте правку назад на скло — де зелена клавіша START зробить із неї нову копію, яку можна перетягнути у вашу DAW.","changelog.05f4a806504e":"<strong>КОПІР і СТУДІЯ.</strong> Дві вкладки над машиною — <code>Ctrl+1</code> і <code>Ctrl+2</code> (<code>Cmd</code> на Mac) звідусіль, або стрілки між ними. Перемикання нічого не зупиняє: копія, яка сканується, і далі робиться за Студією, а її сторінки вже вийдуть, коли ви повернетеся. Кожен екземпляр пам’ятає свою вкладку.","changelog.c3cc9f721474":"<strong>Відкрити в Студії.</strong> Клавіша <strong>СТУДІЯ</strong> на сенсорному екрані відкриває копію, що лежить у лотку; у браузері <strong>Відкрити в Студії</strong> відкриває копію файлу, вибраного в «Копіях». Копія аудіолупа відкриває свої MIDI-сторінки, по вкладці на кожну, у порядку сторінок; аудіокопія відкриває партії MIDI, з якого її зроблено. Ноти читаються з файлів, які записала копія, — копію, чиї файли переміщено або змінено, буде відхилено, і Студія пояснить чому.","changelog.93f13976feb6":"<strong>Піано-рол MIDI Master.</strong> Намалюйте ноту подвійним клацанням; перетягніть ноту, щоб зсунути її; потягніть її лівий край <code>[</code> або правий край <code>]</code>, щоб подовжити чи вкоротити її; виділення рамкою, клацання із Shift і з Ctrl; копіювання, вирізання, вставлення, клонування (<code>Shift+D</code> або перетягування з Alt), видалення (Delete, Backspace або клацання правою кнопкою); зсув стрілками; доріжка сили натиску внизу; прив’язка до сітки; скасування й повтор. Ударні показують голоси свого набору за назвами збоку.","changelog.71cc9842a84d":"<strong>Послухайте.</strong> ВІДТВОРИТИ, ЗУПИНИТИ і ПОВТОР, а також соло й вимкнення звуку на кожній партії. Звучить саме той файл, який отримає копір, через інструменти, якими друкує копія, — інструмент партії можна змінити просто там. Партія в соло звучить саме так, як прозвучить її сторінка копії, хай би що ще було вимкнено.","changelog.118cc9125c81":"<strong>Надіслати до копіра.</strong> Правку записано як новий MIDI-файл у теку <code>Studio</code> у вашій теці «Копії» — ніколи поверх іншого — і покладено на скло. Натисніть START, і її буде скопійовано як будь-який оригінал; у її паспорті зазначено, з якої копії зроблено правку.","changelog.9ee308e27a53":"<strong>Віяло сторінок ширше.</strong> Кожна сторінка під верхньою показує свій лівий і передній край — досить широко, щоб клацнути її із Shift і взяти; піднята сторінка йде на верх стосу, а сторінки під нею змикаються. Клацання із Shift вибирає сторінку, не зсуваючи стос.","changelog.14a8f0896eef":"<strong>MIDI-файл з однією партією копіюється як партія, названа в його імені.</strong> Файл з однієї лінії, названий за своєю партією, — <code>…-Bass.mid</code>, <code>… - Countermelody - …</code> — копіюється як ця партія, через інструмент цієї партії, а не вгадується з того, наскільки високо чи низько він звучить.","changelog.ba657b6bc761":"Довгий ряд кнопок під вибраним файлом у браузері міг виштовхнути браузер під копір; тепер він переноситься на новий рядок.","changelog.0f03db88ad85":"Файл, який записує копір, ніколи не записується поверх іншого, збереженого мить тому під тим самим іменем другим копіром (іншим екземпляром Flipcopy у вашій DAW); він отримує наступне вільне ім’я.","changelog.438e4f8ca3fc":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">Сенсорний екран</span>","changelog.63f032bc62d6":"Сенсорний екран копіра оживає. З нього розгортаються <strong>Налаштування копіювання</strong> — які партії копіювати, сітка, свінг, темп, інструменти, формат, — і кожне налаштування змінює копію, яку ви робите; клавіші екрана гортають ваші копії, зберігають їх, показують і друкують знову; а копію можна повернути на скло, щоб скопіювати її у зворотний бік.","changelog.fe9572610f3a":"<strong>Налаштування копіювання.</strong> Натисніть <strong>ПАРАМЕТРИ</strong> на сенсорному екрані — і з нього виросте панель. Для аудіолупу: копіюйте <strong>кожну партію</strong>, <strong>лише</strong> одну партію (ударні, басову лінію, мелодію чи акорди — якщо такої партії в лупі немає, копір відмовляє, а не друкує порожню сторінку) або <strong>вокальну лінію</strong>, прочитану по одній ноті; ставте ноти на <strong>сітку</strong> (1/8, 1/16, 1/32 чи 1/16T) і <strong>вирівнюйте</strong> свінг. Для MIDI-файлу: сторінка на партію або <strong>лише мікс</strong>; <strong>інструмент</strong> для кожної партії — шукайте в бібліотеці за назвою, жанром чи родиною — і <strong>драм-машина</strong> (808, 909, 707, 606); <strong>хвіст</strong> після останньої ноти; <strong>WAV</strong>, <strong>AIFF</strong>, <strong>FLAC</strong> або <strong>MP3</strong> (320 kbps), 44.1, 48, 88.2 чи 96 kHz, 16- або 24-бітний чи 32-бітний із рухомою комою. В обох напрямках: <strong>темп</strong> — автоматичний, як у проєкті, власний темп файлу, з назви файлу або заданий вами. Зміни стосуються наступної копії, ніколи не тієї, що вже робиться, і проєкт їх зберігає.","changelog.80133c005eb5":"<strong>Кожна сторінка називає свій інструмент</strong> (ТОНЕР …) поруч зі своїм темпом і тим, звідки він узявся.","changelog.54c5f05f9607":"<strong>Темп із назви файлу — як пропозиція.</strong> MIDI-файл без власного темпу, у назві якого темп указано (<em>Hook 127 BPM.mid</em>), отримує плашку біля екрана: <em>Використати 127 BPM</em> копіює файл у цьому темпі; темп проєкту ніколи не змінюється.","changelog.762dc63396b4":"<strong>Стос.</strong> ◀ <strong>НАЗАД</strong> і <strong>ДАЛІ</strong> ▶ (або <code>[</code> і <code>]</code>) гортають ваші копії, і кожна лежить у лотку, готова до перетягування; <strong>ЗБЕРЕГТИ</strong> зберігає верхню сторінку як новий файл у вибраному вами форматі; <strong>ПОКАЗАТИ</strong> показує її в теці; <strong>ПЕРЕДРУК</strong> повертає оригінал копії на скло з тими налаштуваннями, з якими її зроблено, — натисніть START, щоб зробити її знову.","changelog.5e9b6523831f":"<strong>Копія копії.</strong> Сторінка, перетягнута назад на скло — або кинута з «Копій», — лягає як оригінал, а нова копія повідомляє, з якої сторінки її зроблено.","changelog.9c72fd49cbf7":"<strong>Кілька сторінок одразу.</strong> Клацайте сторінки із Shift, щоб вибрати їх; перетягніть одну — і підуть усі, у порядку сторінок.","changelog.c754df195ab0":"<strong>Паспорт копії.</strong> У теці кожної копії лежить <code>ticket.txt</code>: оригінал і його цифровий відбиток, налаштування, темп і звідки він узявся, інструменти, сесія, у якій копію зроблено, а також файл і цифровий відбиток кожної сторінки. <code>flipc copy --ticket</code> робить ту саму копію знову, байт у байт.","changelog.14e910f0a79b":"<strong>Налаштування.</strong> Швидкість (<strong>Швидка</strong> проганяє машину за короткими таймінгами), <strong>Зменшення руху</strong> (за налаштуванням системи або завжди), <strong>Тека «Копії»</strong> (<strong>Змінити…</strong> і <strong>Показати в теці</strong> — нові копії потрапляють у нову теку, старі лишаються там, де є), окремий перемикач звуків інтерфейсу, а також ліцензії та угода в розділі «Про програму».","changelog.54aac57413aa":"<strong>Звуки інтерфейсу.</strong> «Налаштування», «Налаштування копіювання» і браузер відкриваються, закриваються, ховаються й з’являються з короткими, м’якими, скляними звуками, кожен рівно такої довжини, як його рух, — через власний вихід плагіна, ніколи в bounce, і вимикаються окремим перемикачем.","changelog.49cc52f4d8b8":"<strong><code>flipc copy</code></strong> приймає всі налаштування копіювання: <code>--parts</code>, <code>--grid</code>, <code>--swing</code>, <code>--stems</code>, <code>--toner</code>, <code>--drums</code>, <code>--format</code>, <code>--rate</code>.","changelog.b58b14c86e76":"<strong>На сторінку під верхньою</strong> можна натиснути там, де вона виглядає з-за краю лотка.","changelog.b0befc5e6040":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">Файловий браузер і програвач попереднього прослуховування</span>","changelog.e884ffe2f90e":"Знайдіть семпл або MIDI-кліп, послухайте його, подивіться на нього й покладіть на скло — браузер і програвач попереднього прослуховування з Freally Oscillate поруч із копіром. Усе найважливіше на місці: MVP готовий.","changelog.130b73a201db":"<strong>Браузер.</strong> Він відкривається на своїх категоріях — <strong>Копії</strong>, усі сторінки й мікси, які ви зробили, і <strong>Нещодавні</strong>, оригінали, які ви востаннє клали на скло, у кожної — лічильник, — а далі теки, які ви додаєте кнопкою <strong>+ Додати теку</strong> (до 128). Тека на від’єднаному диску зберігає своє місце й повідомляє про це; клацніть теку правою кнопкою миші або виберіть її й натисніть <code>Delete</code>, щоб більше її не переглядати, і на диску нічого не зміниться. <strong>Назад</strong> і <strong>Уперед</strong> проводять місцями, де ви побували, точнісінько як у Freally Oscillate.","changelog.3c76294f691c":"<strong>Тека як дерево.</strong> Розгортайте й згортайте її, друкуйте, щоб відфільтрувати, звужуйте до тегу або до своїх позначених і виберіть <strong>Показувати всі файли</strong>, щоб побачити службові файли, які вона приховує (<code>.asd</code>, <code>.reapeaks</code> тощо). <code>↑</code>/<code>↓</code> пересувають рядками, і кожен, на який ви потрапляєте, звучить один раз; <code>→</code> відкриває теку, <code>←</code> закриває її, а <code>Enter</code> кладе файл на скло.","changelog.9e19fd75f5c5":"<strong>Індексування, за яким можна стежити.</strong> Нова тека підраховується в окремому потоці, а смуга показує, наскільки просунувся підрахунок, — не глибше 12 рівнів тек і не більше 50 000 файлів, без переходів за ярликами за межі теки.","changelog.7e5083732503":"<strong>Програвач попереднього прослуховування</strong>, закріплений під браузером. Аудіо показує свою справжню форму хвилі; MIDI-файл показує свої ноти й звучить через <strong>Preview Piano</strong> — той самий звук і той самий рендер, що використовує копія, тож попереднє прослуховування і є копією. <code>Space</code> запускає й призупиняє; клацніть або потягніть по смузі, щоб перемістити курсор відтворення, який рахує до останньої ноти музики, а не до тактової риски; є повтор, відтворення під час вибору й рівень. WAV будь-якої тривалості відтворюється потоком; інший формат грає, якщо триває п’ять хвилин або менше. Програвач звучить через власний вихід плагіна й ніколи не потрапляє в bounce.","changelog.ca065d9e7b42":"<strong>Послухайте копію, перш ніж вона піде.</strong> Клацніть оригінал на склі або будь-яку сторінку в лотку, щоб прослухати її; коли копія готова, <strong>Копія</strong> програє всі сторінки разом, а <strong>Оригінал</strong> — скло, з того самого місця в музиці. Це необов’язково: сторінки перетягуються, щойно ляже остання, прослухані чи ні.","changelog.d17537ff40ec":"<strong>Перетягування на скло.</strong> Рядок або смуга попереднього прослуховування — у такій самій лаймовій рамці, як сторінка, — перетягнута на копір, кладе цей файл на скло, а за вказівником рухається його мінівідбиток. Нічого не починається до START.","changelog.cda58c5f73eb":"<strong>Сховайте браузер</strong> поєднанням <code>Ctrl+B</code> (<code>Cmd+B</code> на Mac) або кнопкою на його краю: сцена займе все вікно, а обертовий заголовок знову стане по центру. Flipcopy це запам’ятовує.","changelog.5d236e4be21d":"<strong>Повідомити про проблему просто із застосунку.</strong> Коли збій стається в самому Flipcopy, екран пропонує <strong>Повідомити</strong> — це відкриває сторінку звіту у вашому веббраузері й показує, що саме вона містить; нічого не надсилається, доки ви не натиснете там «Надіслати».","changelog.49de87a64bae":"<strong>Сайт документації</strong> зібрано зі спільного набору для сайтів Freally, однакового на кожному сайті Freally, а його посібник оновлено для цієї версії.","changelog.b0f81c543dda":"<strong>Сторінка під вказівником знаходиться за будь-якого розміру вікна.</strong> Клацання чи перетягування по сторінці влучало не туди, якщо вікно було масштабоване.","changelog.2096d3c4bbd8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">Аудіо → MIDI: чарівна мить</span>","changelog.df6f06284fdc":"Покладіть аудіолуп на скло, натисніть START — і з нього вийде MIDI: по сторінці на кожен шар, який чує копір, одна за одною з одного сканування, кожна окремим файлом, у лаймовій рамці, щоб перетягнути їх у DAW поодинці або всі разом. MIDI-файл із кількома партіями виходить так само: по аудіосторінці на партію і весь файл одним міксом.","changelog.24a7fe5481b4":"<strong>Аудіо → MIDI.</strong> Аудіолуп розкладається на шари — ударні, бас, мелодію, <strong>контрмелодію</strong>, якщо в лупі є друга, незалежна лінія, та акорди — класичним DSP-екстрактором MIDI Master (без ШІ). Кожен знайдений шар — це окрема сторінка й окремий <code>.mid</code> з назвою, як її показує DAW (<em>Loop - Bassline - 120 BPM - C# Minor</em>); шар, якого немає, сторінки не отримує, а луп зовсім без нот відхиляється, а не копіюється порожнім. Тональність друкується, лише якщо її прочитано впевнено.","changelog.0c3d252fc872":"<strong>Стос сторінок.</strong> Сторінки виходять одна за одною з єдиного сканування й віялом лягають у лоток, у кожної — заголовок за її формою та партією (<em>MIDI МЕЛОДІЯ</em>, <em>АУДІО БАСОВА ЛІНІЯ</em>) з позначкою <em>СТОРІНКА n/N</em>. Клацніть сторінку, щоб підняти її нагору. <strong>Нічого не перетягується, доки не ляже остання сторінка.</strong>","changelog.55fa665ebb50":"<strong>Два перетягування з готового стосу.</strong> Верхня сторінка має дві лаймові вкладки: <strong>Усі партії</strong> перетягує кожну сторінку окремим файлом, і DAW розкладає їх по одній доріжці на шар; <strong>Повний мікс</strong> перетягує один файл з усім — багатодоріжковий <code>.mid</code> з усіма партіями або весь рендер як <code>.wav</code>, — записаний поруч зі сторінками й ніколи не надрукований. Наведіть курсор на вкладку, щоб побачити дані міксу; без вказівника його зберігає команда <em>Зберегти повний мікс як…</em>.","changelog.7ab067eeb165":"<strong>MIDI → аудіо, партія за партією.</strong> MIDI-файл із кількома партіями друкує по аудіосторінці на партію (<em>АУДІО МЕЛОДІЯ</em>, <em>АУДІО БАСОВА ЛІНІЯ</em>), кожну відрендерено окремо й намальовано з власного WAV, плюс Повний мікс — партії в сумі дають мікс за одного спільного підсилення із запасом за рівнем.","changelog.71cfe75f90c6":"<strong>Лупи до 16 тактів.</strong> Скло відхиляє довший кліп, називаючи його довжину в тактах, і ніколи його не обрізає; луп в один, два чи чотири такти й далі копіюється. Такти аудіолупу рахуються в тому темпі, в якому його читає копір.","changelog.6aed786b024a":"<strong>Чесні сторінки.</strong> Сторінка «Акорди» каже, що це прогресія, а не зігране розташування; якщо вокальну лінію почуто й залишено як є, про це каже перша сторінка, а луп, у якому є лише вокальна лінія, відхиляється саме з таким поясненням, а не словами «нема чого копіювати». Кожен надрукований темп називає своє джерело — прочитаний із лупу або, коли удари лупу не лягають на жодну сітку, взятий із хоста, з назви файлу чи за замовчуванням.","changelog.cb05cd0fc0f0":"<strong><code>flipc</code></strong> — командний рядок, що запускає власні скло й копір плагіна: <code>flipc copy &lt;file&gt; --out &lt;dir&gt;</code>, <code>flipc facts &lt;file&gt;</code> (блок даних точно таким, яким його друкує папір), <code>flipc score</code> (оцінювання корпусу) і <code>flipc bench</code> (заміри часу).","changelog.d2365b73e8bc":"<strong>Перевірка корпусу.</strong> Корпус audioTest оцінюється під час кожного локального прогону CI, де він є, — а де його немає, виводиться SKIPPED — за порогами, які лише зростають.","changelog.d2a673b21c8f":"<strong>Темп хоста відстежується блок за блоком</strong>, а MIDI-файл без власного темпу копіюється в тому темпі хоста, який був у мить натискання START.","changelog.ee270218636c":"<strong>Темп сесії лише розв’язує октавну неоднозначність.</strong> Луп на 120 BPM, кинутий у сесію на 90 BPM, читається як 120 (чотири такти), а не 90 (три) — виправлено в спільному екстракторі MIDI Master для всіх продуктів Freally, що читають лупи.","changelog.ab8ac52d964e":"<strong>Безкоштовно зараз, але не обіцяно назавжди.</strong> Freally Flipcopy зараз безкоштовний, але може не залишитися безкоштовним назавжди: майбутні версії можуть продаватися. Тепер про це сказано на кожній сторінці сайту документації.","changelog.7fb464e21cf8":"<strong>Репозиторій переїхав</strong> до власного облікового запису GitHub супровідника — закритий, усі права захищено; спільні крейти Freally беруться із сусідніх Freally MIDI Master і Freally Oscillate, а вебадреса плагіна — нова адреса сайту документації.","changelog.c584da8d5dfd":"<strong>Безперервна інтеграція працює на машині супровідника</strong> перед кожним пушем — усі перевірки на Windows, а перевірки для Linux у Docker Desktop — і жодної в GitHub Actions. Кожен коміт містить <code>[skip ci]</code>. (Кілька годин 2026-09-30 репозиторій був публічним, і CI запускалася на GitHub під час кожного пуша.)","changelog.79a07e8925af":"<strong>Редактор має власний профіль браузера.</strong> Дані WebView2 Flipcopy (<code>%APPDATA%\\Freally Flipcopy\\webview</code>) зберігалися в теці Freally MIDI Master, а два продукти зі спільним профілем WebView2 можуть залишити один одному порожній редактор, коли обидва працюють в одній DAW. Тепер профіль належить лише Flipcopy.","changelog.72de476110e3":"<strong>Повний мікс копії може бути лише її власним файлом</strong>: <code>record.json</code>, змінений в обхід копіра, не може спрямувати перетягування, «Зберегти як» чи «Показати в теці» деінде.","changelog.427549a6dab4":"<strong>Копія записується цілком або не записується зовсім.</strong> Усі сторінки й мікс опиняються на диску раніше, ніж будь-що з них отримає свою назву, тож збій на півдорозі ніколи не залишає сторінок у пронумерованій теці, що не належить жодній копії.","changelog.2604a6288e96":"<strong>Жодного кліпінгу на сторінках.</strong> Єдине підсилення із запасом визначається за кожним файлом, який записує копія, — партія може мати пік вищий за мікс там, де інші її гасять.","changelog.c6cb2c38dd63":"<strong>16-тактовий луп, експортований на тік довшим, — це 16 тактів</strong>, а не 17: остання нота, відпущена на тридцять другу пізніше тактової риски, не утворює окремого такту.","changelog.2ba628500475":"<strong>Контролери потрапляють на сторінку</strong> навіть на каналі, де не звучить жодна нота.","changelog.833039ba4e85":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-30\">2026-09-30</time></span><span class=\"release__title\">Копір і перша копія</span>","changelog.35409a92a233":"Копір стоїть на сцені й програє епізоди сюжетних роликів копіра з Blender у їхньому порядку: киньте MIDI-файл на скло, натисніть зелену клавішу START — і в лоток виходить справжня аудіокопія: надрукована з власного файлу, у лаймовій рамці, готова до перетягування просто у вашу DAW.","changelog.c12f4045ef96":"<strong>Копір на сцені.</strong> Апарат, відрендерений тією самою сценою Blender, що й обидва сюжетні ролики, — основа, кришка у вигляді кадрів спрайта, натиснуті клавіші, маски скла й лотка — намальований поверх власного тла вікна (<code>#090c09</code>) на прозорій плівці, тож він стоїть у кімнаті без жодного шва. Фази — це епізоди роликів у їхньому порядку (аркуш перевертається й лягає лицем донизу, кришка зачиняється з відскоком, звучить сигнал START, лампа ходить з боку в бік, і з передньої щілини просочується світло кольору ціан, поки вся кімната тьмяніє, копія виїжджає в лоток) зі скороченими тривалостями версії для застосунку; тест не проходить, якщо застосунок колись програє епізод, якого немає в сюжеті, пропустить якийсь або програє їх не за порядком. Копір заповнює все місце, яке дає йому вікно, і ніколи не віддзеркалюється в мовах із письмом справа наліво.","changelog.81d392181aa1":"<strong>Зелена клавіша START — єдиний тригер.</strong> Кинутий кліп лише лягає на скло. START (або <code>Ctrl/Cmd+Enter</code>, що натискає ту саму клавішу) запускає копіювання; STOP (або <code>Esc</code>) скасовує його посеред сканування, нічого не залишаючи по собі; HOME очищає скло. На клавіші — похилий напис <em>START</em>, повернутий до сенсорної панелі, а її світлодіод світиться щоразу, коли копіювання можна почати. Тест плагіна надсилає кожну команду й не проходить, якщо завдання запускає будь-що, крім <code>copier_start</code>, а перевірка збірки не проходить, якщо сторінка колись надішле її звідкись, окрім клавіші START.","changelog.3c73db8b1385":"<strong>Скло.</strong> Киньте аудіо- або MIDI-файл із Провідника чи Finder будь-куди у вікні (скло підсвічується, коли файл наближається) або натисніть <code>Enter</code> на порожньому склі, щоб вибрати його. Файл читається в окремому потоці й друкується лицем догори, перш ніж ляже, — справжні ноти або справжня форма хвилі, з даними самого файлу. Мережеві шляхи, завеликі, задовгі, тихі, пошкоджені файли, MIDI-файли з часом у SMPTE та формату 2 відхиляються, кожен зі своєю фразою. Два файли водночас: перший лягає на скло, а апарат повідомляє, що кліпи приймаються по одному. Новий кліп, кинутий на готову копію, так само лягає на скло, а лоток очищується (копія залишається в теці «Копії»). Файл, який скло відхилило, залишає кліп, що на ньому лежав, на місці.","changelog.4267b3fd96ac":"<strong>MIDI → аудіо.</strong> Копія рендерить ноти файлу через тонер за замовчуванням — власні пресетні голоси MIDI Master для звуковисотних партій і драм-машину, по голосу на кожну лінію GM, для ударних — з урахуванням пітч-бенду й педалі сустейну (педаль кожного каналу діє лише на ноти цього каналу), з хвостом 2.5 с, у темпі файлу (інакше — хоста, якого в окремого застосунку немає, інакше — з назви файлу, інакше 120, і сторінка називає джерело), утримується нижче −0.3 dBFS і записується як 24-бітний WAV із частотою дискретизації хоста (44.1 кГц в окремому застосунку), який DAW ставить на сітку долей. Копія може бути такої довжини, з якої ще можна надрукувати сторінку, — п’ять хвилин або 2:30 понад 48 кГц, — а довша відхиляється до рендеру й ніколи не обрізається. Аудіо → MIDI з’явиться у <code>v0.3.0</code>; доти START на аудіокліпі чесно про це повідомляє.","changelog.d9714ba71fa5":"<strong>Тека «Копії»</strong> (<code>Documents/Freally Flipcopy/Copies</code>): по одній пронумерованій теці на копію, яку займають атомарно, щоб дві DAW ніколи не отримали той самий номер; сторінки називаються так, як їх показує DAW (<code>Title - Part - 120 BPM, Key.wav</code>); кожну сторінку записано атомарно, перечитано й перевірено — і її <strong>ніколи не переміщують, не перезаписують і не видаляють</strong>, бо ваша DAW посилається на неї за шляхом.","changelog.48b3f94d470b":"<strong>Відбитки — із самих файлів.</strong> Кожна сторінка — оригінал на склі й копія в лотку — друкується лазером, як відбитки в сюжетних роликах: заголовок, рядок джерела, лінійка тактів, піано-рол із доріжкою велосіті або форма хвилі з новою <strong>смугою спектра</strong> та блок даних — усе це плагін обчислює з байтів на диску. Такт у непарному розмірі зберігає свою половину долі (7/8 друкується як три з половиною долі на такт). Сторінка копії каже, що її рендер пропустив, — контролери, яких він не зіграв, ноти ударних, для яких у кіті немає голосу, — і ніколи не губить їх мовчки. Тест читає структуру сторінок застосунку й самих відбитків роликів і звіряє їх між собою.","changelog.fa6958b17901":"<strong>Перетягніть копію у DAW.</strong> На сторінці, що вийшла, навколо кліпу — лаймова рамка з написом <em>Перетягніть у DAW</em> під нею — рамка і є ручкою. Натисніть усередині неї й зсуньте на 4 px — і перетягується власний файл копії (з міні-відбитком біля курсора) у FL Studio, Ableton, Reaper чи будь-яку DAW, що приймає файли. Нічого не перетягується, доки сторінка не вийде повністю; там, де перетягування неможливе, рамка стає сірою й пунктирною і натомість пропонує «Зберегти як». <code>Enter</code> на сторінці відкриває «Зберегти як» або показує файл у його теці.","changelog.4da7005c5000":"<strong>Звуки машини</strong>, синтезовані з нуля для цього копіра (укладання, кришка, сигнал, початок сканування, по одному гудінню на кожен прохід лампи, викид), мікшуються плагіном у його власний вихід — ніколи через HTML <code>&lt;audio&gt;</code> — на −18 дБ через рівень Monitor, стихають, поки грає ваша DAW (в окремого застосунку немає транспорту DAW, заради якого стихати), мовчать під час офлайн-bounce і ніколи не замінюють звук вашої доріжки. У «Налаштуваннях» їх можна ввімкнути чи вимкнути, задати гучність і вибрати «Тихо, поки DAW грає».","changelog.f8fc9e0d2e58":"<strong>Сенсорний екран</strong> показує, що робить апарат, який кліп у ньому лежить, і кожну відмову — мовою продюсера.","changelog.1a5ee7d7aabc":"<strong>Перевірки</strong> для всього цього, кожну з яких спершу бачили проваленою, перш ніж їй довіряти: трійка збігу тла (кольори рендеру дорівнюють токенам; ΔE2000 навколо власного альфа-силуету апарата в кожній фазі за DPR 1 і 2; між апаратом і тлом нічого не малюється), перевірка START (статична, у плагіні й у Playwright), відповідність відбитків, пікселі рамки перетягування та нові специфікації гілки застосунку в справжньому окремому застосунку.","changelog.66b1e687636a":"<strong>Спільний код</strong>: <code>freally-extract</code> (вхід декодування й аналіз аудіо), <code>freally-encode</code> (WAV, ресемплінг, чанки сітки DAW) і <code>freally-drag</code> (нативне джерело перетягування) беруться з MIDI Master на <code>shared-v5</code>, а <code>freally_library::audition::NoteRenderer</code>, події контролерів у <code>read_facts</code>, а також хук кидання файлів адаптера вебподання, його перерозміщення вебподання під час переміщення вікна та його порожній заголовок додано там, у вихідному проєкті.","changelog.e7908191194e":"<strong>Значок — авторська робота власника</strong> — лаймова <em>F</em> поверх форми хвилі й піано-ролу — на виконуваному файлі, пакетах плагіна, значках Linux і macOS та на сайті документації замість заглушки.","changelog.719f74499130":"<strong>Вікно.</strong> Рядок заголовка окремого застосунку має значок, він темний, кольору кімнати, і нічого не каже: немає назви ні в рядку заголовка окремого застосунку, ні у вікна плагіна в DAW, чий підпис називає Flipcopy, адже обертова назва вгорі вікна вже її називає. Ця обертова назва вдвічі більша, щоб читатися з одного погляду, і вирівняна по центру над частиною вікна з копіром; файловий браузер тягнеться від верху вікна до доку попереднього прослуховування поруч із ним.","changelog.120afa46c010":"Міст приймає запити до 2 МіБ (зображення перетягування); <code>host_info</code> повідомляє, чи можна тут перетягнути сторінку.","changelog.df29ffbf7480":"Доки ліцензійну угоду не прийнято, сторінка редактора може прочитати мову інтерфейсу й нічого більше — через власну команду (<code>locale_get</code>); <code>prefs_get</code> відповідає лише після прийняття.","changelog.bf4a28a43b62":"<strong>Переміщення вікна на масштабованому дисплеї.</strong> Коли у Windows був масштаб 150 %, під час перетягування вікна окремого застосунку за рядок заголовка його вміст малювався на третину позаду вікна, у бік верхнього лівого кута екрана, ховаючи правий і нижній краї, доки вікно не повертали в той кут. Тепер вміст залишається точно під вікном, куди б його не переміщували.","changelog.f246f03536b6":"<strong>Окремий застосунок — у власному масштабі вашого дисплея.</strong> На масштабованому дисплеї (150 %) окремий застосунок працював як стара, немасштабована програма: Windows розтягувала його вікно, а сторінка всередині малювалася в справжніх пікселях — звідси й перелічені тут зміщення перетягування та випадних списків. Тепер, перш ніж відкрити вікно, він оголошує підтримку DPI для кожного монітора окремо, як окремі застосунки Freally MIDI Master і Freally Unloop, тож сторінка малюється чітко в масштабі дисплея, а вікно відкривається задуманого розміру.","changelog.4d43aa80977a":"<strong>Список мов відкривається під своїм полем.</strong> На масштабованому дисплеї системний випадний список відкривався нижче й правіше від поля в «Налаштуваннях» — тим далі, чим далі поле було від кута вікна; тепер список малює сам Flipcopy, просто під полем, у темному стилі вікна, і кожну мову написано її власним письмом.","changelog.a348e37f07eb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">Фундамент і хребет CI</span>","changelog.8847996db9e9":"Порожній продукт, на якому будується кожен наступний щабель: він завантажується, пропускає звук недоторканим, просить прийняти ліцензійну угоду, відкриває своє темне вікно, і працюють усі перевірки якості.","changelog.cc29ebe17a90":"<strong>Плагін у всіх форматах з одного бінарного файлу.</strong> CLAP-плагін на nih-plug із точками входу VST3 і AUv2, які створює <code>clap-wrapper</code> (чисто за ліцензіями: без GPL-прив’язок VST3), плюс <strong>окремий застосунок</strong> — нативний настільний застосунок із власним вікном та аудіопристроєм, ніколи не вебзастосунок. Стереовхід і стереовихід, нотний вхід для майбутнього «Сканування з доріжки», нульова затримка, а звук доріжки проходить <strong>біт у біт</strong> (це доводить нуль-тест). Перемикач <strong>Bypass</strong> у хості й рівень <strong>Monitor</strong> для звуку, який додасть сам Flipcopy (звуки машини й попереднє прослуховування, з <code>v0.2.0</code>), — доріжки він ніколи не торкається. Версіонований збережений стан, обмежений за розміром, який мігрується й відхиляється цілком, а не завантажується наполовину, тож пошкоджений проєкт ніколи не обвалить хост.","changelog.59616adfaedb":"<strong>Ліцензійна угода</strong> (<code>EULA.md</code>, побудована як у Freally Oscillate) та блокування до її прийняття: Flipcopy просить прийняти її під час першого відкриття й доти бездіяльний — нічого не читає, нічого не копіює й нічого не додає до вашої доріжки. Угода вкомпільована в плагін і подається з нього, кнопка «Погоджуюся» чекає, доки текст не буде дочитано до кінця, а ваша відповідь спільна для всіх відкритих екземплярів і окремого застосунку. Якщо відмову не вдалося зберегти, про це повідомляється.","changelog.ed5631790156":"<strong>Вікно</strong>, що відкривається розміром 1400 × 875 (як у Freally Unloop) і масштабується цілим до будь-якого розміру — усе зберігає пропорції, без смуг навколо, — під рядком заголовка, де <em>Freally Flipcopy</em> і номер версії обертаються в 3D навколо осі Y, так само як у Freally Oscillate і Freally MIDI Master (і завмирають у режимі зменшеного руху): темна оболонка з панеллю браузера й доком попереднього прослуховування на боці початку рядка, перетягуваний роздільник (260–420 px, також клавішами зі стрілками) і сцена — без власного тла, тож копір стоятиме в кімнаті без шва навколо. Одна тема, темна, і нічого, що могло б створити другу.","changelog.ccf91016802f":"<strong>Вісімнадцять мов</strong> для всього у вікні; вибір зберігається для комп’ютера й спільний для всіх екземплярів; розкладка справа наліво для арабської.","changelog.92d766745704":"<strong>Шрифти Noto від Google</strong>, включені до пакета за ліцензією SIL Open Font License 1.1, з текстом ліцензії поруч із ними.","changelog.b502e66ba7a3":"<strong>Сайт документації</strong>, побудований як у Freally Oscillate й лише темний, тими самими вісімнадцятьма мовами (кожна завантажується, лише коли читач її обере): головна сторінка з драбиною версій (генерується з <code>docs/ladder.json</code> і звіряється із закритим планом перевіркою), дві історії копіра з Blender у розділі «Подивіться, як він копіює», документація, цей журнал змін і сторінка завантаження, яка прямо каже, що до <code>v1.0.0</code> завантажувати нічого. Історії відтворюються зі звуком, лише коли ви натиснете похилий START на зеленій клавіші копіра (або кнопку відтворення), і зупиняються на першому кадрі, коли закінчуються або їх зупиняють; історія аудіо → MIDI друкує по сторінці на кожен шар — MIDI Мелодія, MIDI Акорди, MIDI Басова лінія та MIDI Контрмелодія — одну за одною в стос у лотку, кожну в лаймовій рамці з написом <em>Перетягніть у DAW</em> під нею.","changelog.96a59e69b7f8":"<strong>Текст залишається всередині своїх контейнерів</strong> усіма 18 мовами, за вікна за замовчуванням і найменшого (перевірка Playwright кожного підпису).","changelog.495bcdf8956e":"<strong>Перевірки</strong>, кожну з яких спершу бачили проваленою, перш ніж їй довіряти: форматування, clippy, усі тести, перевірка типів, лінт, перевірка локалей (18 каталогів, однакові ключі та плейсхолдери, справді перекладені), лінт логічного CSS, дизайн-токени й контраст, лише темна тема, список заборон (без ШІ, без мережі, без телеметрії), аудит ліцензій, перевірка спільних крейтів (використовувати, ніколи не форкати), назви продуктів (ніколи торговельна марка виробника копірів), дрейф прив’язок, драбина, жодних завантажень до 1.0, бюджет ресурсів, <code>clap-validator</code> і <code>pluginval</code> за суворості 10, локальна CI на Windows і в Docker для Linux, а також Playwright на двох гілках — браузер і справжнє вікно окремого застосунку.","changelog.8f6fb4eb7f42":"Безпека","changelog.09dd8d0ea4e1":"Редактор завантажує лише сторінку, вкомпільовану в бінарний файл, під суворою Content Security Policy; його міст відповідає лише на власний JSON-запит <code>POST</code> сторінки, відхиляє все понад 64 КіБ і будь-який шлях із <code>..</code>, а до прийняття угоди відповідає лише на команди з дозволеного списку. Релізні збірки не відкривають ні DevTools, ні порту віддаленого налагодження.","changelog.e06fbd4d3359":"У плагіні та окремому застосунку немає мережевого коду — це перевіряють компілятор (<code>clippy.toml</code>) і граф залежностей (<code>scripts/check-denylist.mjs</code>).","changelog.70e17daefb45":"Файли, які Flipcopy зберігає в теці даних застосунку (відповідь на угоду й налаштування), читаються з обмеженням розміру й записуються атомарно, тож пошкоджений або вручну відредагований файл завантажується як значення за замовчуванням, а збій ніколи не залишає половину файлу."};
